window.ASKV={"sezonlar":[{"no":1,"ad":"Piyasaya Giriş","alt":"Kim, kimi, neden seçer?"},{"no":2,"ad":"Sözleşme","alt":"Evlilik, ev ve emek"},{"no":3,"ad":"Kriz","alt":"İlişki sarsılınca"},{"no":4,"ad":"Dijital Çağ","alt":"Kaydırılan kalpler"}],"turAd":{"profil":"Profil","senaryo":"Ne yapardın?","mit":"Mit mi, gerçek mi?","cift":"Çift testi","hesap":"Hesaplayıcı","nesil":"Nesil testi","karne":"Final"},"bolum":{"01":"Aşk Nedir?","02":"Aşk ve Rasyonalite","03":"Kıtlık","04":"İhtiyaç, Arzu ve Tercih","05":"Aşk Piyasası","06":"Sinyaller","07":"Güzellik Ekonomisi","08":"Para ve Servet","09":"Denklik ve Benzerlik","15":"Evliliğin Ekonomisi","16":"Görünmeyen Emek","17":"Çocukların Ekonomisi","18":"Çok Eşlilik","19":"Kıskançlık Ekonomisi","22":"Boşanmanın Ekonomisi","23":"Aldatma ve İhanet Ekonomisi","24":"Güven Sermayesi","25":"İlişkiye Yatırım","26":"Fırsat Maliyeti","27":"Seçenek Bolluğu","28":"Beklenti Enflasyonu","29":"Modern Evlilik","30":"Tinder’dan Önce ve Sonra","31":"Aşkın Endüstrisi","32":"Küreselleşen Mahremiyet","33":"Yalnızlığın Ekonomisi","34":"Geleceğin Aşk Ekonomisi"},"testler":[{"no":1,"slug":"fiyatin-ne","ad":"Aşk piyasasında fiyatın ne?","tur":"profil","bolum":"05","sezon":1,"acilis":"2026-10-06","kanca":"Sevgilinin fiyat etiketi yok, ama senin gözünde aşkın bir bedeli var.","sorular":[["Bir ilk buluşmada seni en çok ne soğutur?",[["Z","Son dakika iptal etmesi"],["D","Sürekli telefonuna bakması"],["G","Anlattıklarının birbirini tutmaması"],["O","İkinci buluşmayı hemen planlamaya kalkması"],["H","Her şeyin fazla sıradan geçmesi"]]],["Hangi jest seni kazanır?",[["Z","En yoğun haftasında sana bir akşam ayırması"],["D","Bir ay önce söylediğin küçük bir ayrıntıyı hatırlaması"],["G","Söylediği saatte, söylediği yerde olması"],["O","“Bu hafta sonu kendine zaman ayır” demesi"],["H","Hiç denemediğiniz bir şeyi birlikte yapmayı önermesi"]]],["Bir ilişkide neyi “zarar” hanesine yazarsın?",[["Z","Hep bir sonraki haftaya ertelenen planları"],["D","Yarım kulakla dinlenmeyi"],["G","Küçük de olsa yalanları"],["O","Her adımının sorgulanmasını"],["H","Her günün bir öncekinin kopyası olmasını"]]],["Arkadaşın yeni sevgilisini anlatıyor. Hangi cümle seni ikna eder?",[["Z","“Ne kadar yoğun olsa da bana vakit ayırıyor.”"],["D","“Beni gerçekten dinliyor.”"],["G","“Ne dediyse yaptı.”"],["O","“Kıskanç değil, beni rahat bırakıyor.”"],["H","“Onunla hiç sıkılmıyorum.”"]]],["Hangi cümle sana daha yakın?",[["Z","Sevgi, birine ayrılan saatlerle ölçülür."],["D","Görülmek, sevilmekten önce gelir."],["G","Söz, sözleşmeden sağlamdır."],["O","Sevmek tutmak değil, bırakabilmektir."],["H","Rutin, aşkın sessiz katilidir."]]],["Bir tartışmadan sonra barışmanın en hızlı yolu?",[["Z","Hemen gelip yüz yüze konuşmak"],["D","Ne hissettiğimi gerçekten anlamaya çalışmak"],["G","Tutulabilecek bir söz vermek"],["O","Biraz zaman tanıyıp sonra konuşmak"],["H","Beni bir anda güldürecek çılgın bir fikir"]]]],"sonuclar":{"Z":["Senin bedelin: Zaman","Senin için sevginin en inandırıcı kanıtı takvimde açılan yerdir. Kitap zamanı aşkın en temel kıt kaynaklarından biri sayar: Kimse güne yirmi beşinci saati ekleyemez. Bir saatin anlamı da hangi koşulda ve neyden vazgeçilerek verildiğine bağlıdır. Bedeli şu: Yoğun bir dönemdeki partneri sevgisizlikle suçlamak kolaylaşır. Kitap uyarır: “Bana zaman ayırmıyor, demek ki beni sevmiyor” çıkarımı her durumda doğru değildir.","03"],"D":["Senin bedelin: Dikkat","Sen sevilmeden önce görülmek istiyorsun. Aynı masada oturmak yetmez, zihnin de orada olmalı. Kitaba göre romantik ilişkide para dışındaki kıt kaynaklar da sinyal taşır ve dikkat bunların başında gelir. Pahalı ama kişisiz bir hediye seni etkilemez. Aylar önce söylediğin küçük bir ayrıntıyı hatırlayan ucuz bir hediye ise dikkat hakkında güçlü bilgi taşır. Bedeli şu: Dikkat her an ölçülebildiği için hayal kırıklığı da her an üretilebilir.","06"],"G":["Senin bedelin: Güven","Senin para birimin tutarlılık: Söylenen saatte orada olmak, verilen küçük sözü tutmak. Kitap güveni bir sermayeye benzetir. Geçmiş davranışlardan birikir ve ilişkinin günlük işlem maliyetini düşürür. Ama banka hesabı gibi işlemez: Küçük bir gecikme yılların güvenini silmeyebilir, tek büyük ihanet ise bütün geçmişin yorumunu değiştirebilir. Bedeli şu: Kitaba göre sürekli yeni kanıt isteyen ilişki, hiçbir sinyalin yeterince güvenilir sayılmadığı ilişkiye dönüşebilir.","24"],"O":["Senin bedelin: Alan","Seni kazanmanın yolu seni tutmaya çalışmamaktan geçiyor. Kitap insanların ilişkiden beklediklerinin farklı olduğunu söyler: Biri için sık görüşmek ilişkinin kalitesinin temel göstergesidir, başka biri için kişisel alanın korunması aynı derecede değerlidir. Sende ikincisi ağır basıyor. Kitaba göre mahremiyet, partnerden gizli ikinci bir hayat sürdürmekle aynı şey değildir. Bedeli şu: Sık temas isteyen biri, alan ihtiyacını ilgisizlik diye okuyabilir.","24"],"H":["Senin bedelin: Yenilik","Senin için en büyük maliyet sıkılmak. Aynı hafta sonu düzeni sana güven değil durgunluk gibi gelir. Kitap bu konuda bir araştırma aktarır: Birlikte yeni ve uyarıcı deneyimler yaşamak bazı çiftlerde ilişki kalitesini destekleyebilir. Ama kitaba göre yenilik harcamanın büyüklüğüyle değil, rutin dışı ortak deneyimin niteliğiyle ilgilidir. Bedeli şu: İnsan yeni deneyimlere de alışabilir ve hayatı sürekli uyarılma arayışına çevirmek sürdürülebilir değildir.","25"]}},{"no":2,"slug":"kacan-mi-kovalanan-mi","ad":"Kaçan mısın, kovalanan mı?","tur":"profil","bolum":"03","sezon":1,"acilis":"2026-10-06","kanca":"“Kaçan kovalanır” derler, peki sen hangisisin?","sorular":[["Hoşlandığın biri mesajına 6 saat sonra cevap verdi. Sen?",[["K","Ben de en az 7 saat beklerim"],["V","Hemen yazarım, belki bir şey olmuştur"],["D","Ne zaman müsaitsem o zaman yazarım"],["S","Hiç yazmam, zaten bir şey çıkmazdı"]]],["İlk buluşmanın sonunda…",[["K","“Ararım” derim, birkaç gün aramam"],["V","Eve varmadan “çok güzeldi” yazarım"],["D","Hoşlandıysam bunu açıkça söylerim"],["S","Bir sonraki adımı ona bırakırım"]]],["Seni en çok kim cezbeder?",[["V","Kolay ulaşılamayan, gizemli biri"],["K","Benim için çabalayan, emek veren biri"],["D","Ne istediğini açıkça söyleyen biri"],["S","Beni hiç zorlamayan, yavaş ilerleyen biri"]]],["Bir ilişkide hep ulaşılabilir olmak sana nasıl hissettirir?",[["K","Değerimin düştüğünü hissederim"],["V","Huzurlu, ben zaten hep oradayım"],["D","Karşılıklıysa güzel"],["S","Biraz boğucu"]]],["Arkadaşların seni nasıl tarif eder?",[["K","“Onu yakalamak zor.”"],["V","“Sevince her şeyini verir.”"],["D","“Ne istediğini bilir.”"],["S","“Hep izler, nadiren adım atar.”"]]],["Hangi cümleye katılırsın?",[["K","Değer, ulaşılmazlıktan doğar."],["V","Sevgi saklanmaz, gösterilir."],["D","Oyun oynayan kaybeder."],["S","Hiç başlamayan ilişki bitmez de."]]]],"sonuclar":{"K":["Kaçan: Kıtlık stratejisi","Arzını bilerek kısıyorsun: Geç cevap, belirsiz plan, biraz mesafe. Ulaşılmaz kalmanın değerini artıracağını düşünüyorsun. Kitap bu sezgiyi bütünüyle reddetmez ama sınırını çizer: Kıtlık tek başına değer yaratmaz, kıt olan şeyin aynı zamanda istenmesi gerekir. Bedeli şu: Kitaba göre cevap vermemek, sürekli uzak durmak veya karşı tarafı belirsizlik içinde tutmak bazı durumlarda ilgiyi artırmak yerine ilişkiyi sona erdirebilir.","03"],"V":["Kovalayan: Güçlü talep","Sevdiğinde hesabı kitabı bırakıyorsun, ilk adımı atan çoğu zaman sen oluyorsun. Bu cömertlik güzel. Ama kitabın aşk piyasası bölümü bir kuralı hatırlatır: Romantik ilişkide aynı anda iki tercih sistemi çalışır ve karşındakinin de seni seçmesi gerekir. Kitabın deyişiyle “Çok istemek, tek başına eşleşme üretmez.” Bedeli şu: Yaptığın fedakârlık karşılığı garanti eden bir bedel değildir, çünkü sevgilinin fiyat etiketi yoktur.","05"],"D":["Dengede: Açık sinyal","Oyun oynamıyorsun. Ne istediğini söylüyor, karşılığını bekliyorsun. Kitap burada bir ayrım yapar: Söz ucuzdur, çünkü samimi olmayan kişi de aynı cümleyi kolayca kurabilir. Senin açıklığını inandırıcı yapan, söylediklerinle yaptıklarının zaman içinde uyuşmasıdır. Kitaba göre uzun ilişkinin güçlü sinyallerinden biri gösteriş değil tutarlılıktır. Bedeli şu: Aynı davranış bir insan için güçlü ilgi, başka biri için sınır ihlali gibi görünebilir.","06"],"S":["Seyirci: Kenarda bekleyen","Risk almaktansa beklemeyi seçiyorsun. Reddedilme ihtimali kazanma ihtimalinden ağır basıyor. Kitap romantik kararların fiyatının yalnız para olmadığını söyler: Reddedilme riski ve duygusal kırılganlık da kararın maliyetleri arasındadır. Senin için bu maliyet yüksek. Bedeli şu: Kitabın hatırlattığı gibi “Karar vermemek de zaman geçtiği için fiilen bir karardır.” Beklerken kaçan fırsatlar hiçbir faturada görünmez, ama fırsat maliyeti tam da orada durur.","26"]}},{"no":3,"slug":"kalp-mi-akil-mi","ad":"Kalbin mi hesap yapıyor, aklın mı?","tur":"senaryo","bolum":"02","sezon":1,"acilis":"2026-10-06","kanca":"Kalple akıl gerçekten düşman mı, altı zor seçimde kendini dene.","sorular":[["İki seçenek var: Seni heyecanlandıran ama düzensiz yaşayan biri, ya da güvenilir ama “kıvılcım”ı olmayan biri.",[["R","Güvenilir olan. Kıvılcım sonradan gelir, istikrar gelmez."],["T","Heyecan. Hayat bir kere."],["S","İlk andaki hissim neyse o."],["D","İkisiyle birer kez daha buluşur, sonra karar veririm."]]],["Sevgilin başka bir şehirde iş teklifi aldı.",[["R","Kira, ulaşım, kariyer… artı-eksi listesi yaparım."],["T","Nereye giderse peşinden giderim."],["S","İçime ne doğarsa onu yaparım."],["D","Önce ne istediğimizi konuşur, sonra hesap yaparız."]]],["Gece ikide büyük bir kavga ettiniz. “Bitti” demek üzeresin.",[["R","Sakinleşince artı-eksi listesi yapar, öyle karar veririm."],["T","O an ne hissediyorsam söylerim, sonrası sonra."],["S","Bu tür kavgaların nereye gittiğini önceki ilişkilerimden bilirim."],["D","Kararı sabaha bırakırım, sabah da aynı görünüyorsa ciddiye alırım."]]],["Arkadaşların seni biriyle tanıştırdı. Kâğıt üzerinde bütün kriterlerine uyuyor ama hiçbir şey hissetmedin.",[["R","Bir şans daha veririm, kriterlerimi boşuna koymadım."],["T","Kıvılcım yoksa yoktur, devam etmem."],["S","İlk izlenimim neyse odur, nadiren yanılır."],["D","Birkaç kez daha görüşürüm, his bir bilgi ama tek bilgi değil."]]],["“Aşk kördür” sözü için ne dersin?",[["R","Kör değil, hesabı sonra yapar."],["T","Kördür ve iyi ki öyledir."],["S","Kör değil, sadece çok hızlıdır."],["D","Başta kördür, zamanla gözlüğünü takar."]]],["Evlilik kararı ne zaman verilir?",[["R","Ekonomik ve pratik koşullar hazır olunca"],["T","Doğru kişiyi bulduğun an"],["S","Bir gün “işte bu” diye hissettiğinde"],["D","Hem içinden geldiğinde hem şartlar elverdiğinde"]]]],"sonuclar":{"R":["Kalbin bir muhasebeci","Sen sevmiyor değilsin, sadece sevginin hesabını da tutuyorsun. Kitaba göre bu soğukluk değil: Ekonomik rasyonellik en çok parayı getiren seçeneği bulmak değil, değer verdiğin farklı amaçlar arasında seçim yapabilmektir. Bedeli şu: Her şeyi sürekli tartmak bağlılığı erteleyebilir. Kitabın ölçüsü açık: “Rasyonellik ilişkinin sürekli muhasebesini yapmak değil, önemli yeni bilgi geldiğinde eski hükmü değiştirebilme kapasitesini korumaktır.”","02"],"T":["Kalbin bir kumarbaz","Sen büyük oynarsın. Riskleri görürsün ama kalbinin sesine uyarsın. Kitap bunu otomatik olarak irrasyonel saymaz: Ortak hayat senin için vazgeçtiğin şeyden değerliyse seçimin kendi tercihlerin içinde anlaşılabilir. Ama yoğun özlem anındaki “Onsuz yaşayamam” hissinin geleceği kusursuz tahmin etmediğini de hatırlatır. Bedeli şu: Kitaba göre rasyonellik burada duygusuzluk değil, geri dönüşü zor kararları birden fazla duygusal durumda değerlendirebilmektir.","02"],"S":["Kalbin bir kestirme yol","Sen uzun hesap yapmıyorsun ama rastgele de karar vermiyorsun. Sezgilerin, yaşadıklarından süzülmüş hızlı kurallar. Kitap Tversky ve Kahneman’ın klasik çalışmalarından yola çıkarak bu kestirmelerin belirsizlikte karar vermeyi kolaylaştırdığını, ama bazen sistematik hatalara yol açabildiğini anlatır. Bedeli şu: Yakın zamanda yaşanan kötü bir ayrılık yeni insanlara ilişkin risk algını büyütebilir. Kitabın ölçüsü, sezginin hangi durumda ne kadar iyi rehber olduğunu fark edebilmektir.","02"],"D":["Kalp ile akıl ortaklığı","Ne körü körüne atlıyorsun ne de her şeyi tabloya döküyorsun. Önce hissediyor, sonra kontrol ediyorsun. Kitap tam bu ayrımı savunur: “Onu seviyor muyum?” ile “Onunla yaşayabilir miyim?” farklı sorulardır. Duygu neyi önemsediğini bildirir, akıl sonuçları düşünmene yardım eder. Bedeli şu: Bu yol yavaştır. Kararı fazla uzatırsan, kitabın dediği gibi karar vermemek de zaman geçtiği için fiilen bir karara dönüşür.","02"]}},{"no":4,"slug":"ilk-bulusma-sinyali","ad":"İlk buluşmada verdiğin sinyal aslında ne diyor?","tur":"profil","bolum":"06","sezon":1,"acilis":"2026-10-06","kanca":"Sen bir şey söylüyorsun, karşındaki başka bir şey duyuyor.","sorular":[["İlk buluşmanın yerini nasıl seçersin?",[["E","Onun sevdiği şeyleri araştırıp ben seçerim"],["V","Şık, adı bilinen bir yer"],["D","“Ben şurayı severim, sen ne dersin?” diye sorarım"],["G","Son ana kadar söylemem, sürpriz olsun"]]],["Ne giyersin?",[["E","Özenle hazırlanırım, emek belli olsun"],["V","En iyi, en göz önündeki parçamı"],["D","Her zaman nasılsam öyle"],["G","Biraz farklı bir şey, çözmeye çalışsın"]]],["Kendinden ne kadar bahsedersin?",[["E","Az, daha çok onu dinlerim"],["V","Başarılarımdan, gezdiğim yerlerden"],["D","İyisiyle kötüsüyle ne varsa"],["G","Çok az, merak etsin"]]],["Hesap geldi.",[["E","Ben öderim, bu benim jestim"],["V","Kartımı hemen çıkarırım"],["D","Bölüşmeyi teklif ederim"],["G","Gülümser, ne yapacağına bakarım"]]],["Buluşmadan sonra…",[["E","Konuştuklarımıza gönderme yapan uzun bir mesaj"],["V","Bir fotoğraf ya da story"],["D","“Çok keyif aldım, tekrar görüşelim.”"],["G","Ertesi güne kadar hiçbir şey"]]],["Karşındaki hangi cümleyi kurarsa etkilenirsin?",[["E","“Bunun için uğraştığın belli.”"],["V","“Çok etkileyicisin.”"],["D","“Seninle rahat hissediyorum.”"],["G","“Seni çözemedim.”"]]]],"sonuclar":{"E":["Emek sinyali","Sen “seni seviyorum” demek yerine bedeli olan şeyler yapıyorsun: Zaman, özen, araştırma. Kitap romantik ilişkide bazı güçlü sinyallerin cüzdandan değil takvimden geldiğini söyler. Taklit edilmesi güç davranışlar daha fazla bilgi taşıyabilir. Bedeli şu: Kitaba göre “Maliyet tek başına samimiyet sertifikası değildir.” Karşındaki emeğini görür, ama ne anlama geldiğine o karar verir.","06"],"V":["Vitrin sinyali","Sen gücünü ve imkânlarını görünür kılıyorsun: Şık mekân, iddialı kıyafet, başarı hikâyeleri. Kitap bunu Veblen’in gösterişçi tüketim kavramıyla açıklar. Banka hesabı görünmez, ama mekân ve yaşam tarzı ekonomik kapasite hakkında işaret verebilir. Bedeli şu: Kitaba göre servet sinyalinin birden fazla yorumu olabilir. Pahalı restoran sana cömertlik, karşındakine gösteriş gibi görünebilir. Paranın görünür olması, herkesin gördüğünden hoşlanacağı anlamına gelmez.","08"],"D":["Şeffaflık sinyali","Sen kartlarını açık oynuyorsun. Kitaba göre söz tek başına zayıf bir sinyaldir: Güvenilir insan da güvenilmez insan da kendini güvenilir diye tanıtabilir. Senin açıklığını değerli kılan, söylediğin gibi davranmaya devam etmen. Kitabın örneğiyle ilk buluşmadaki nezaket küçük bir veridir, altı ay boyunca gözlenen tutarlılık çok daha fazlası. Bedeli şu: Açıklık ilk anda göz kamaştırmayabilir. Getirisi zamanla birikir.","06"],"G":["Gizem sinyali","Sen bilgiyi kısarak merak üretiyorsun. Kitap bunun işe yarayabileceğini kabul eder: Belirsizlik, ulaşılmazlık veya tutarsızlık bazen duygusal yoğunluğu artırabilir. Ama hemen ekler: “Yoğunluk ile ilişkinin kalitesi aynı değişken değildir.” Bedeli şu: Kitaba göre insanlar görünmeyen nitelikler hakkında gözlenebilir davranışlardan çıkarım yapar. Az veri verirsen çıkarımı karşındaki yapar. Gizem ilk buluşmayı kazandırabilir, ilişkiyi ise güven taşır.","02"]}},{"no":5,"slug":"guzellik-mitleri","ad":"Güzellik hakkında inandığın 6 şeyden kaçı doğru?","tur":"mit","bolum":"07","sezon":1,"acilis":"2026-10-06","kanca":"“Güzellik bakanın gözündedir” derler ama araştırmalar o kadar emin değil.","sorular":[["Görünüşü ortalamanın altında değerlendirilen kişiler, iş hayatında ortalama görünümlülerden daha az kazanabilir.",true,"Doğru. Hamermesh ve Biddle’ın 1994 tarihli klasik çalışmasında, ortalamanın altında çekici bulunanların ortalama görünümlülere göre yaklaşık yüzde 5–10 daha düşük kazanç elde ettiği bulundu. Kitap yine de uyarır: Bu bulguyu “Güzel olursanız yüzde şu kadar daha fazla kazanırsınız” formülüne çevirmemek gerekir."],["Güzellik primi her işte aynı büyüklükte ortaya çıkar.",false,"Yanlış. Kitabın aktardığı bir deneyde (Deryugina ve Shurchkov, 2015) çekici çalışanlara daha yüksek ücret teklifi, görünüşün performansla ilgili olmasının beklendiği görevde çıktı. Analitik ve veri girişi görevlerinde benzer prim görülmedi. Gerçek performans bilgisi ortaya çıktıkça görünüşün etkisi de azalabildi."],["Kimin güzel olduğu konusunda insanlar birbirinden çok farklı düşünür.",false,"Yanlış, en azından sanıldığı kadar değil. Langlois ve arkadaşlarının (2000) on bir meta-analizden oluşan çalışması, insanların kimin çekici olduğu konusunda hem aynı kültür içinde hem kültürler arasında belirli düzeyde görüş birliği gösterebildiğini ortaya koydu. Kitap bunun tek ve evrensel bir güzellik standardı anlamına gelmediğini de ekler."],["Çekici bulunan insanlar başka yönlerden de daha olumlu değerlendirilebilir.",true,"Doğru. Psikolojide buna çekicilik stereotipi, daha geniş anlamıyla halo etkisi denir. Langlois ve arkadaşlarının meta-analitik değerlendirmesinde çekici bulunan çocuk ve yetişkinlerin daha olumlu değerlendirilebildiği görüldü. Kitaba göre bu, onların gerçekten her alanda daha iyi olduğu anlamına gelmez."],["Çiftler fiziksel çekicilik bakımından birbirine benzeme eğilimindedir.",true,"Doğru. Webster ve arkadaşlarının 2024’te eski meta-analitik verileri yeniden değerlendirdiği çalışmada, karma cinsiyetli çiftlerde iki partnerin dış gözlemcilerce değerlendirilen çekicilikleri arasında yaklaşık r = 0,39 düzeyinde pozitif ilişki bulundu. Kitap bunun ortalama bir örüntü olduğunu, bireyin kaderi olmadığını vurgular."],["Gerçek romantik değerlendirmelerde fiziksel çekiciliğin etkisi erkeklerde kadınlardan çok daha büyüktür.",false,"Yanlış. Eastwick ve arkadaşlarının (2014) meta-analitik incelemesinde, varsayımsal partner sorularında verilen cevaplar farklılaşabilse de gerçek romantik değerlendirmelerde çekiciliğin etkisindeki cinsiyet farkı oldukça küçüktü ve anlamlı bulunmadı. Kitaba göre fiziksel çekicilik her iki taraf için de anlamlı rol oynayabilir."]],"seviyeler":[[0,"Vitrine kanan","Güzellik hakkındaki sezgilerinin çoğu, kitabın aktardığı araştırmalarla örtüşmedi. Kitabın deyişiyle “İnsan davranışı sloganlardan daha karmaşıktır.” Kitabın özeti iki cümle: Güzellik önemlidir. Fakat güzellik tek ve nesnel bir değer değildir."],[3,"Göz kararı","Bazılarını doğru bildin, bazılarında yanıldın. Güzelliğin ekonomisi tam da bu yüzden ilginç: Görünüş ilk anda çok bilgi veriyormuş gibi gelir, ama kitabın deyişiyle “Güzel yüz, laboratuvar raporu değildir.”"],[5,"Piyasa analisti","Güzelliğin nasıl ödüllendirildiğini iyi okuyorsun. Şimdi kitabın sorduğu zor soru sende: Toplum hangi alanlarda güzelliği ödüllendiriyor ve bu ödül ne ölçüde işlevsel olarak ilgili?"]]},{"no":6,"slug":"para-konusulunca","ad":"Para konuşulunca ilişkinde ne oluyor?","tur":"senaryo","bolum":"08","sezon":1,"acilis":"2026-10-06","kanca":"Aşk parayla satın alınmaz, peki faturayı kim ödüyor?","sorular":[["İlk buluşmada hesap?",[["O","Davet eden öder, sonra sıra değişir"],["A","Herkes kendi payını öder"],["K","Zaten pahalı olmayan bir yer seçerim"],["C","Ben öderim, tartışmaya gerek yok"]]],["Birlikte yaşamaya başladınız. Kira ve faturalar?",[["O","Hepsi tek, ortak hesaptan"],["A","Herkesin hesabı ayrı, giderler bölüşülür"],["K","Önce bütçe tablosu, sonra karar"],["C","Kim daha rahatsa o öder, saymayız"]]],["Partnerin sana sormadan büyük bir alışveriş yaptı.",[["O","Bozulurum, o bizim ortak paramız"],["A","Kendi parasıysa söz hakkım yok"],["K","Birikim planımızı bozdu mu, ona bakarım"],["C","Mutlu olduysa sorun değil"]]],["Biri ayda 100, diğeri 40 birim kazanıyor. Ortak giderler?",[["O","Kim ne kazanırsa ortak kasaya, giderler oradan"],["A","Gelir oranında, herkes kendi hesabından"],["K","Önce birikim payı ayrılır, kalanı paylaşılır"],["C","Çok kazanan rahatça üstlensin, saymayalım"]]],["Para yüzünden hangi kavga tanıdık geliyor?",[["O","“Bunu neden bana sormadın?”"],["A","“Benim paramla ilgili konuşma.”"],["K","“Yine mi harcadın?”"],["C","“Neden bu kadar hesapçısın?”"]]],["Hangi cümle seni anlatır?",[["O","Evlilik ortaklıksa kasa da ortaktır."],["A","Ayrı cüzdan, sağlam ilişki."],["K","Bugünün aşkı, yarının güvencesiyle büyür."],["C","Para harcamak içindir, hele sevdiğin için."]]]],"sonuclar":{"O":["Ortak kasa","Senin için ilişki bir ortaklık, ortaklığın da tek kasası olur. Kitap bu konuda dikkat çekici bir araştırma aktarır: Gladstone ve arkadaşlarının (2022) çalışmasında parasını tamamen birleştiren çiftler ortalamada daha yüksek ilişki doyumu bildirdi. Ama kitap bunun evrensel bir reçete olmadığını vurgular: Ortak hesap kendiliğinden güven yaratmaz. Bedeli şu: Ortak kasada harcama kararları da ortak olmak zorunda, “Bunu neden bana sormadın?” sorusu buradan doğar.","08"],"A":["Ayrı cüzdan","Sen aşkı paylaşıyorsun, cüzdanı ayrı tutuyorsun. Bu bencillik değil, özerkliği korumanın bir yolu. Kitaba göre ayrı hesap kullanan çift kötü ilişkiye mahkûm değildir. Kitap paranın özgürlükle bağını da vurgular: Kendi geliri olan kişi ilişkide zorunluluktan değil gönüllülükten kalabilir. Bedeli şu: Para dışındaki katkılar, yani zaman ve bakım, bu hesapta kolayca görünmez olur. Kitabın hatırlattığı gibi “Aşk bütçesinin bütün satırları para cinsinden yazılmaz.”","08"],"K":["Tasarruf eden kalp","Senin için para harcanacak değil, korunacak bir şey: Yarının güvencesi. Bu ilişkiye istikrar getirebilir. Ama kitap para kavgalarının çoğu zaman rakamdan değil anlamdan çıktığını söyler: Bir eş için tasarruf güvenlik, diğeri için yaşamın ertelenmesi olabilir. Kitaba göre bütçe rakamlardan, para kavgası ise çoğu zaman değerlerden oluşur. Bedeli şu: Kitabın aktardığı bir çalışmada para tartışmaları en sık yaşanan tartışma değildi, ama diğerlerine göre daha tekrarlayıcı ve çözülmesi daha zor olma eğilimi gösterdi.","08"],"C":["Cömert kalp","Sen sevgiyi biraz da harcayarak gösteriyorsun: Hediye, davet, sürpriz. Kitaba göre para “Seni seviyorum” cümlesinin davranışa dönüşme yollarından biri olabilir. Ama kitap aynı cümlenin tersini de yazar: Para sevginin yerine de konabilir. Bir taraf para üreterek katkı verirken diğeri zaman ve duygusal yakınlık bekleyebilir. Bedeli şu: Kitaba göre para her zaman zamanın, dikkatin ve bakımın tam ikamesi değildir.","08"]}},{"no":7,"slug":"benzer-mi-zit-mi","ad":"Kendine benzeyeni mi seçiyorsun, zıttını mı?","tur":"profil","bolum":"09","sezon":1,"acilis":"2026-10-12","kanca":"Zıt kutuplar birbirini çeker mi, yoksa senin seçimlerin başka bir şey mi söylüyor?","sorular":[["İdeal partnerin hangi konuda sana benzemeli?",[["B","Neredeyse her konuda"],["Z","Hiçbir konuda, yoksa sıkılırım"],["Y","Benden biraz daha ileride olsun"],["T","Değerlerde aynı, yeteneklerde farklı"]]],["Eğitim düzeyi?",[["B","Benimkine yakın olmalı"],["Z","Hiç önemli değil"],["Y","Benden yüksekse daha iyi"],["T","Birbirimizle konuşabildiğimiz sürece fark etmez"]]],["Hafta sonu planı…",[["B","İkimizin de sevdiği aynı şeyi yaparız"],["Z","Ben onun dünyasını keşfederim, o benimkini"],["Y","Onun çevresine girer, yeni insanlar tanırım"],["T","Biri planlar, öbürü uygular"]]],["Tartıştığınızda…",[["B","Nadiren tartışırız, aynı düşünürüz"],["Z","Sık ama heyecanlı"],["Y","Onun bakış açısından öğrenirim"],["T","Biri sakinleştirir, öbürü çözer"]]],["Ailesiyle tanışınca neye bakarsın?",[["B","Benim aileme benzeyip benzemediğine"],["Z","Ne kadar farklı olduklarına"],["Y","Nasıl bir çevreden geldiğine"],["T","Birbirleriyle nasıl anlaştıklarına"]]],["“Tencere yuvarlanmış, kapağını bulmuş.”",[["B","Tam olarak böyle"],["Z","Ben başka bir tencere ararım"],["Y","Kapak, tencereyi biraz yukarı taşımalı"],["T","Tencere ile kapak aynı değil, birbirine uygun"]]]],"sonuclar":{"B":["Ayna: Benzerini seçen","Sen kendine benzeyeni seçiyorsun ve gerçek çiftlerin tablosu sana yakın. Kitaba göre insanlar eğitim, din ve yaşam tarzı gibi birçok özellikte benzerleriyle beklenenden daha sık eşleşir. Buna seçici eşleşme ya da homogami denir. Ama bunun tek nedeni tercih değildir: Aynı okul, işyeri ve mahalle benzer insanları zaten bir araya getirir. Bedeli şu: Kitaba göre benzer eşleşme bazen mevcut eşitsizlikleri aynı hanede yoğunlaştırabilir.","09"],"Z":["Zıt kutup","Sen farklılıktan besleniyorsun, tanımadığın dünya seni çekiyor. Kitap “zıt kutuplar çeker” sözünün gerçek çiftlerin genel tablosuyla pek örtüşmediğini gösterir: İnsanlar birçok özellikte benzerleriyle beklenenden daha sık eşleşir. Ama kitaba göre “benzer benzeri bulur” da tek başına bir ilişki teorisi değildir. Bedeli şu: Bütün farklar aynı değildir. Müzik zevki kolay yönetilir, çocuk isteğinde zıtlık çok daha temel bir çatışma yaratabilir.","09"],"Y":["Bir basamak yukarı","Sen partnerinde biraz ileride olanı arıyorsun: Daha bilgili, daha deneyimli, çevresi daha geniş. İlişkinin seni büyütmesini istiyorsun. Kitap burada yaygın bir dile itiraz eder: “Yukarı evlenmek” gibi ifadeler çok boyutlu insan özelliklerini tek bir sıralamaya indirger. Biri daha eğitimli, öteki daha varlıklı olabilir. Böyle bir çiftte hangisi yukarıda? Bedeli şu: Yukarı bakarken karşındakinin de kendi tercih sıralaması olduğunu unutmak kolaydır.","09"],"T":["Tamamlayıcı","Sen aynılık değil uyum arıyorsun: Değerler ortak, beceriler farklı. Kitap benzerlik ile tamamlayıcılığı rakip değil, farklı boyutlarda birlikte işleyen ilkeler olarak görür. Bir partner planlamada, öteki sosyal ilişkilerde güçlü olabilir. Farklı sektörlerdeki kariyerler riski çeşitlendirebilir. Bedeli şu: Klasik aile ekonomisi tamamlayıcılığı zaman zaman katı bir iş bölümüne bağladı. Kitaba göre uzmanlaşmanın uzun dönemli maliyeti, ayrılık hâlinde taraflardan birinin üzerinde birikebilir.","09"]}},{"no":8,"slug":"ihtiyac-arzu-tercih","ad":"Sevgilin ihtiyaç mı, arzu mu, tercih mi?","tur":"profil","bolum":"04","sezon":1,"acilis":"2026-10-15","kanca":"Onu seviyor musun, yoksa ona ihtiyacın mı var?","sorular":[["Bir hafta hiç görüşemeseniz?",[["I","Eksik ve huzursuz hissederim"],["A","Özlemden yanarım"],["T","Kendi işlerime bakarım, döndüğünde yine o"],["L","Bir şey değişmez, sadece düzenim bozulur"]]],["Onu ilk neden seçtin?",[["I","Yanımdayken kendimi güvende hissettim"],["A","Ondan gözümü alamadım"],["T","Tanıdığım herkes arasında bana en çok o uydu"],["L","Bir şekilde hayatımdaydı, devam etti"]]],["Kâğıt üzerinde daha “uygun” biri çıksa?",[["I","Korkarım ama onu bırakamam"],["A","Uygunluk değil, çekim önemli"],["T","Karşılaştırırım, yine de onu seçerdim diye düşünüyorum"],["L","Değiştirmek zahmetli gelir"]]],["Onunla ilgili en çok neyi seversin?",[["I","Hep orada olmasını"],["A","Bana hissettirdiklerini"],["T","Kim olduğunu"],["L","Her şeyi bilmesini, açıklamak zorunda kalmamayı"]]],["Ayrılık düşüncesi sana ne hissettirir?",[["I","Paniğe kapılırım, onsuz eksik kalırım"],["A","Acı ama yaşanmaya değmiş bir tutku"],["T","Üzüntü, ama hayat devam eder"],["L","Bütün düzenin değişmesi, yorucu"]]],["Hangi cümle daha yakın?",[["I","“O olmadan eksiğim.”"],["A","“Onu istemekten vazgeçemiyorum.”"],["T","“Her sabah onu yeniden seçiyorum.”"],["L","“Onunla her şey kolay.”"]]]],"sonuclar":{"I":["İhtiyaç: Güvenli liman","Senin bağının merkezinde güven ve aidiyet var. Kitaba göre ihtiyaç, iyi oluş için önemli olan genel koşuldur: Yakınlık, aidiyet, güven. Bunların mutlaka romantik ilişki içinde karşılanması gerekmez, ama sende büyük ölçüde onda toplanmış. Bedeli şu: Kitap “birbirimize ihtiyacımız var” cümlesinin iki anlamını ayırır. Birinde insanlar birbirinin hayatını zenginleştirir, diğerinde kişinin başka gerçek seçeneği kalmamıştır. Kitabın deyişiyle “Bağlılık, çıkış imkânının tamamen yokluğu değildir.”","04"],"A":["Arzu: Yanan motor","Senin bağın çekim üzerine kurulu: İstemek, özlemek, gözünü alamamak. Kitaba göre arzu, genel bir ihtiyacın belirli bir kişiye yönelmiş hâlidir. “Yakınlık istiyorum” ile “Ayşe'yle birlikte olmak istiyorum” arasındaki fark tam burada ortaya çıkar. Kitabın deyişiyle “İnsan yakınlığa ihtiyaç duyabilir ama herhangi birine âşık olmaz.” Bedeli şu: Kitap çok güçlü çekim hissedilen kişiyle yaşam tarzının uyuşmayabileceğini de hatırlatır.","04"],"T":["Tercih: Her gün yeniden","Sen onu alternatifleri görüp yine de seçtiğin için yanında tutuyorsun. Kitaba göre tercih, istekler çatıştığında hangisine daha fazla ağırlık verdiğini gösterir. İktisat buna açıklanmış tercih der: Söylediklerimiz kadar gerçek kısıtlar altında yaptığımız seçimler de neyi değerli bulduğumuzu anlatır. Bedeli şu: Kitap burada ihtiyatlıdır. Seçtiğimiz şey her zaman en çok istediğimiz şey değildir, bazen yalnız ulaşabildiğimiz seçenektir.","04"],"L":["Alışkanlık: Ortak tarih","Bağında alışkanlığın payı büyük ve bu kötü bir şey değil. Kitaba göre uzun ilişkide güven, bakım, alışkanlık ve ortak kimlik daha büyük yer tutabilir. Birlikte kurulan tarih başka bir partnerle anında yeniden üretilemez. Bedeli şu: Kitap bir sınır da çizer: “Bir ilişkide uzun süre kalmış olmak tek başına kalmaya devam etmek için yeterli neden değildir.” Kitabın sorusu: Kalmak ne zaman gitmekten pahalıdır?","22"]}},{"no":9,"slug":"askin-alti-tanimi","ad":"Aşkın 6 tanımından hangisi senin?","tur":"profil","bolum":"01","sezon":1,"acilis":"2026-10-19","kanca":"Kanadalı sosyolog John Alan Lee aşkı renkler gibi altı temel tarza ayırdı, sana en yakın olanı hangisi?","sorular":[["Aşk sana en çok neyi hatırlatır?",[["E","İlk görüşte çarpılmayı"],["L","Keyifli bir oyunu"],["S","Yavaş yavaş derinleşen bir dostluğu"],["P","Doğru kişiyle kurulan bir hayatı"],["M","Uykusuz geceleri"],["A","Karşılık beklemeden vermeyi"]]],["İdeal başlangıç?",[["E","Tek bir bakış"],["L","Flört, şaka, hafiflik"],["S","Yıllardır tanıdığın biri"],["P","Ortak hedefleri konuşmak"],["M","Aklından çıkaramadığın biri"],["A","Ona yardım ederken tanışmak"]]],["Bir ilişkide neye dayanamazsın?",[["E","Kıvılcımın sönmesine"],["L","Fazla ciddiyete"],["S","Güvenin sarsılmasına"],["P","Plansızlığa"],["M","Belirsizliğe, cevapsız mesaja"],["A","Sevdiğimin mutsuz olmasına"]]],["Sevgilin sana nasıl hissettirmeli?",[["E","Büyülenmiş"],["L","Özgür"],["S","Evinde"],["P","Güvende ve yolunda"],["M","Vazgeçilmez"],["A","Ona iyi gelen biri"]]],["Ayrılık…",[["E","Tutku bittiyse biter"],["L","Hayat devam ediyor, başkaları da var"],["S","Dostluk kalır"],["P","Mantıklı değilse bitirmek gerekir"],["M","Kabullenmesi çok zor"],["A","O mutluysa ben de razıyım"]]],["Hangi cümle seni anlatır?",[["E","Aşk, kalbin hızlanmasıdır."],["L","Aşk, ciddiye alınmayacak kadar güzel bir oyundur."],["S","Aşk, en iyi arkadaşınla yaşlanmaktır."],["P","Aşk, doğru ortağı seçmektir."],["M","Aşk, ya hep ya hiçtir."],["A","Aşk, vermektir."]]]],"sonuclar":{"E":["Eros: Tutku","Senin için aşk güçlü romantik ve fiziksel çekimle başlar. Lee bu tarza eros der. Kitap erken romantik aşkta beynin ödül ve motivasyon sistemlerinin etkinleşebildiğini aktarır, ama “aşk uyuşturucu gibidir” sonucuna hızla geçmemek gerektiğini de ekler. Bedeli şu: Kitaba göre otuz yıllık evlilikte aşkın bileşenleri değişir, özlemin yerini güven, bakım ve ortak kimlik alabilir. Asıl soru, kıvılcımın gündelik hayata nasıl taşınacağı.","01"],"S":["Storge: Dostluk","Senin aşkın yavaş yanar ama uzun sürer. Lee bu tarza storge der: Arkadaşlık ve zaman içinde gelişen yakınlık. Gösterişli başlangıçlardan çok birikmiş ortak geçmişe inanıyorsun. Kitap güveni de böyle tarif eder: Tek bir jestten değil, farklı koşullarda gözlenen davranışların birikmesinden oluşan bir sermaye. Bedeli şu: Yavaş kurulan bir bağ, hızlı ilerlemek isteyen birine ilgisizlik gibi görünebilir.","24"],"L":["Ludus: Oyun","Sen aşkı hafif, keyifli ve bağlayıcı olmayan bir oyun gibi yaşıyorsun. Lee bu tarza ludus der: Oyunsu ve düşük bağlılıklı ilişki tarzı. Seçeneklerin açık kalmasını seviyorsun. Bedeli şu: Kitaba göre bütün kapıları açık tutmanın da fırsat maliyeti var, çünkü partnerin de ilişkinin her an değiştirilebileceğini düşünüp aynı ölçüde yatırım yapmayabilir. Kitabın deyişiyle “Özgürlük, kapıyı kapatmanın kendi kararımız olmasıdır.”","26"],"P":["Pragma: Akıllı seçim","Sen aşkı doğru ortağı seçmek olarak görüyorsun: Değerler, hedefler, hayat planı. Lee bu tarza pragma der: Pratik ve uyumluluk odaklı aşk. Bu soğukluk değil. Kitaba göre asıl mesele hangi konuda benzerliğin gerektiğini bilmektir: Müzik zevkindeki fark kolay yönetilir, çocuk isteğindeki zıtlık çok daha temel bir çatışma yaratabilir. Bedeli şu: Kitabın uyarısıyla romantik uyum, benzerlik sayısını topladığımız bir puan değildir.","09"],"M":["Mania: Yoğunluk","Senin aşkın yoğun: Ya hep ya hiç. Mesaj gelmediğinde huzursuzlanıyor, belirsizlikte zorlanıyorsun. Lee bu tarza mania der ve kitap onu yoğun bağımlılık ve kıskançlıkla ilişkili bir aşk biçimi olarak tarif eder. Derin hissedebilmek bir zenginlik. Bedeli şu: Kitaba göre kıskançlığın varlığı ilişkinin değerli olduğunu gösterebilir, ama şiddeti sevginin miktarını ölçmez. Kitabın sorusu: Neyi kaybetmekten korkuyoruz?","19"],"A":["Agape: Vermek","Senin için aşk karşılık beklemeden vermek. Sevdiğinin iyiliği seninkinden önce geliyor. Lee bu tarza agape der: Özgeci ve verici aşk. Kitap bu tarzların değişmez kişilik tipleri olmadığını da hatırlatır. Bedeli şu: Kitaba göre bakım iyi yapıldığında görünmez hâle gelebilir. Kitabın ölçüsü: Bir kişinin bakım vermeyi sevmesi, bu sorumluluğun sonsuza kadar yalnız ona ait olması gerektiği anlamına gelmez.","16"]}},{"no":10,"slug":"birbirinizi-fiyatlamak","ad":"Birbirinizi ne kadar doğru “fiyatlıyorsunuz”?","tur":"cift","bolum":"05","sezon":1,"acilis":"2026-10-22","kanca":"Ayrı ayrı çözün, sonra ikinizin aynı şeylere ne kadar değer verdiğini karşılaştırın.","sorular":[["Bir akşam:",["Evde baş başa","Arkadaşlarla dışarıda"]],["Beklenmedik bir para geldi:",["Tatile","Birikime"]],["Tartışınca:",["Hemen konuşalım","Soğuyunca konuşalım"]],["Sevgi en çok böyle gösterilir:",["Sözle","Davranışla"]],["Yaşanacak yer:",["Büyükşehir","Sakin bir kasaba"]],["Ortak giderler:",["Yarı yarıya","Gelire göre"]],["Telefonlar:",["Şifreler paylaşılır","Herkesin kendi alanı"]],["Bayram ve tatiller:",["Ailelerle","İkimiz"]],["Gelecek:",["Planlı","Akışına"]],["Ev işleri:",["Görev listesiyle","Kim müsaitse"]]],"seviyeler":[[0,"Farklı fiyat listeleri","Neredeyse her konuda farklı şeylere değer veriyorsunuz. Bu bir hüküm değil. Kitaba göre aşk piyasasında eşleşme iki ayrı tercih sıralamasının kesişmesidir ve sizin kesişim alanınız bu on maddede dar görünüyor. Farklı cevap verdiğiniz maddeler, ikinizin de bakmaya değer bulabileceği bir harita."],[3,"Farklı para birimleri","Bazı konularda aynı, bazılarında farklı şeylere değer veriyorsunuz. Kitabın para bölümündeki örnek size tanıdık gelebilir: Bir eş için tasarruf güvenlik, diğeri için yaşamın ertelenmesi olabilir. Ayrıldığınız maddeler belki tercihten çok, aynı şeye yüklediğiniz farklı anlamdan doğuyor."],[6,"Yakın kur","Çoğu konuda aynı şeylere değer veriyorsunuz. Kitaba göre romantik uyum, benzerlik sayısını topladığımız bir puan değildir. Asıl soru, ayrıldığınız maddelerin hangisinin müzik zevki gibi kolay yönetilir, hangisinin çocuk isteği gibi temel olduğu."],[9,"Aynı fiyat listesi","Neredeyse her şeyi aynı biçimde değerlendiriyorsunuz. Yine de kitap bir şeyi hatırlatır: Aşk piyasası vardır, ama sevgilinin fiyat etiketi yoktur. Bugünkü örtüşme yarını garanti etmez. Kitaba göre insan farklı yaşlarda aynı partner özelliklerine aynı ağırlığı vermek zorunda değildir."]]},{"no":11,"slug":"evlilik-ne","ad":"Evlilik senin için yatırım mı, sigorta mı, ortaklık mı?","tur":"profil","bolum":"15","sezon":2,"acilis":"2026-10-26","kanca":"Nikâh masasında herkes aynı imzayı atar ama herkes aynı şeyi imzalamaz.","sorular":[["Biri sana “Neden evlenmek?” diye sorsa ilk cümlen ne olur?",[["Y","Birlikte kalıcı bir şey inşa etmek için"],["S","Zor günde yanımda biri olsun diye"],["O","İki kişi bir ekip olunca hayat daha iyi işler"],["T","Hayatı onunla paylaşmak daha keyifli"],["H","İlişkimizin resmî bir güvencesi olsun diye"]]],["Evlilikte en çok neyin “ortak” olduğunu düşünürsün?",[["Y","Evin, birikimin, uzun vadeli planların"],["S","Kötü günlerin ve sürprizlerin"],["O","Günlük işlerin ve sorumlulukların"],["T","Tatillerin, zevklerin, boş zamanın"],["H","Hakların ve yükümlülüklerin"]]],["Partnerin işini kaybetti. Aklından ilk ne geçer?",[["Y","Ortak planlarımızı nasıl koruruz?"],["S","Bunun için varız, bir süre benim gelirim yeter."],["O","Evdeki iş bölümümüzü yeniden düzenleriz."],["T","Birlikte geçireceğimiz zaman arttı, iyi değerlendirelim."],["H","Resmî haklarımızı ve güvencelerimizi gözden geçiririm."]]],["Nikâh sence bir ilişkiye ne ekler?",[["Y","Ortak yatırımlara cesaret"],["S","Geleceğe karşı bir dayanışma sözü"],["O","Rollerin ve görevlerin netleşmesi"],["T","Birlikte kurulan hayatın kutlaması"],["H","Hukuken tanınan bir haklar paketi"]]],["Bir evlilikte seni en çok ne yıpratırdı?",[["Y","Ortak bir geleceğe yatırım yapamamak"],["S","Zor anda yalnız bırakılmak"],["O","İşlerin hep birinin üstünde kalması"],["T","Birlikte keyif alacak bir şey bulamamak"],["H","Kuralların ve hakların belirsiz kalması"]]],["Hangi cümle sana daha yakın?",[["Y","Evlilik, geleceğe birlikte yapılan bir yatırımdır."],["S","Evlilik, iyi günde de kötü günde de bir güvencedir."],["O","Evlilik, iyi işleyen bir iş bölümüdür."],["T","Evlilik, hayatı birlikte yaşamayı seçmektir."],["H","Evlilik, iki kişinin yazılı sözüdür."]]]],"sonuclar":{"Y":["Evlilik senin için: Yatırım","Senin için evlilik, geleceğe birlikte yapılan bir yatırım: ortak ev, ortak plan, uzun vade. Kitap bunlara ilişkiye özgü yatırım der, çünkü ilişki bitince çoğu başka yerde aynı değeri taşımaz. Hukuken tanınan ortaklık, “Yarın hiçbir şey olmamış gibi çekip gitmeyeceğim” mesajını daha inandırıcı kılabilir. Bedeli de var: Birinin kariyerinden vazgeçtiği bir uzmanlaşma, ayrılık hâlinde maliyeti tek kişinin üstünde biriken bir yatırıma dönüşebilir.","15"],"S":["Evlilik senin için: Sigorta","Senin için eş, hayatın belirsizliklerine karşı kurulan küçük bir dayanışma ağı. Biri işini kaybedince öbürünün geliri sürer, hastalıkta zaman ve kaynak yeniden dağıtılır. Kitap “iyi günde kötü günde” sözünü tam böyle okur: belirsiz geleceğe karşı karşılıklı bir taahhüt. Ama bir uyarı da ekler: Aile kusursuz bir sigorta şirketi değildir. Kenya’da evli çiftlerle yapılan bir deney, eşler arasındaki risk paylaşımının eksik kalabildiğini gösterdi.","15"],"O":["Evlilik senin için: Ortaklık","Sen evliliği iyi işleyen bir ekip olarak görüyorsun: Herkes iyi yaptığı işi üstlenir, hane birlikte üretir. Gary Becker’ın 1973 tarihli evlilik teorisi de evliliği romantizmin karşıtı olarak değil, kazanç üreten bir ortaklık olarak inceledi. Hane yalnız tüketmez, zamanı kullanarak kendi içinde değer üretir. Riskli tarafı şu: Toplam üretim yüksek olsa da piyasa geliri yalnız bir kişinin adına yazılabilir ve evdeki emek görünmez kalabilir.","15"],"T":["Evlilik senin için: Yol arkadaşlığı","Senin için evlilik, tek başına yapamadığın işleri bölüşmek değil, birlikte yapmayı sevdiğin şeyleri ortaklaştırmak. İktisatçılar Stevenson ve Wolfers buna tüketim tamamlayıcılığı der: ortak zevkler, seyahatler, projeler. Kitaba göre modern evlilikte bu yön, klasik iş bölümünden daha önemli hâle gelmiş olabilir. Bedeli şu: Ekonomik zorunluluk azaldıkça “Bu insanla neden kalıyorum?” sorusunun cevabı giderek daha çok gönüllülüğe dayanır.","15"],"H":["Evlilik senin için: Sözleşme","Senin için nikâh, sevginin yanında yazılı bir güvence. Kitap da nikâhı birçok hukuk sisteminde önceden hazırlanmış bir haklar ve yükümlülükler paketi olarak görür: miras, ortak mülkiyet, sosyal güvenlik, ayrılık kuralları. Yani belirsiz geleceğe karşı hukuki bir koordinasyon mekanizması. Ama kitap bir çizgi de çeker: Bağlılık ile hapis aynı şey değildir. İyi kurum, bağlılığı güçlendirirken onun özgür bir seçim olarak kalmasını da korur.","15"]}},{"no":12,"slug":"gorunmeyen-emek","ad":"Görünmeyen Emek Hesaplayıcı: Evde kimin mesaisi yazılmıyor?","tur":"hesap","bolum":"16","sezon":2,"acilis":"2026-10-29","kanca":"Bazı işler kimsenin bordrosuna yazılmaz ama birinin gününden düşer.","sorular":[["Evde deterjan, ekmek ya da diş macunu bitmek üzereyken bunu genelde kim fark eder?",[[0,"Neredeyse hiç ben değilim"],[1,"Bazen ben, bazen başkası"],[2,"Çoğunlukla ben"],[3,"Hep ben, listeyi de ben tutarım"]]],["Doktor randevuları, doğum günleri, ödeme tarihleri gibi şeyleri kim aklında tutar?",[[0,"Başkası hatırlatır, ben uyarım"],[1,"Herkes kendi işini hatırlar"],[2,"Çoğunu ben hatırlarım"],[3,"Evin takvimi benim kafamda"]]],["İşten ya da okuldan eve döndüğünde ne olur?",[[0,"Gün benim için biter, dinlenirim"],[1,"Arada bir küçük işler yaparım"],[2,"Çoğu akşam bir iki saat daha çalışırım"],[3,"Asıl yoğunluk eve gelince başlar"]]],["Evde biri kırgınsa ya da akrabalar arasında gerginlik varsa ortamı kim yumuşatır?",[[0,"Genelde başkası"],[1,"Kim müsaitse o"],[2,"Çoğunlukla ben"],[3,"Hep ben, herkes de bunu benden bekler"]]],["Bir iş birine verildi. Gerçekten yapılıp yapılmadığını kim takip eder?",[[0,"Takip eden başkası"],[1,"Takibe gerek kalmaz, yapılır"],[2,"Çoğu zaman ben kontrol ederim"],[3,"Ben sormasam yapılmaz"]]],["Evden biri hastalanınca ya da bakım gerekince kim işini veya planını değiştirir?",[[0,"Genelde başkası"],[1,"Sırayla ya da birlikte"],[2,"Çoğunlukla ben"],[3,"Hep ben, çalışma düzenim de buna göre şekillendi"]]]],"seviyeler":[[0,"Görünür mesai","Sonuçlara göre evin görünmeyen işlerinin büyük bölümü sende birikmiyor. Bu, gerçekten paylaşılan bir düzen de olabilir, yükün başka birinde toplanması da. Kitabın kutusundaki soruyu düşün: Deterjanın azaldığını kim fark etti, alışveriş listesine kim ekledi? Zihinsel yük iyi yapıldığında sorun çıkmaz, bu yüzden yapılan iş de fark edilmez. Bu bir ölçüm değil, bir düşünme aracı."],[30,"Paylaşılan mesai","Görünmeyen işlerin bir kısmı sende, bir kısmı başkasında. Kitaba göre adalet her şeyi yarı yarıya bölmek değildir: Biri yemeği, öbürü faturaları üstlenebilir, çalışma saatleri farklıysa eşit görev bile adil olmayabilir. Araştırmalar, nesnel dağılım kadar algılanan hakkaniyetin de ilişki doyumuyla bağlantılı olduğunu gösteriyor. Bu bir düşünme aracı: Hangi maddelerde yükün sende toplandığına bak."],[55,"Gizli yönetici","Evde işler yapılıyor olabilir ama neyin yapılacağını fark eden, hatırlayan ve takip eden büyük ölçüde sensin. Allison Daminger bu bilişsel emeği dört aşamada inceler: ihtiyacı önceden fark etmek, seçenekleri belirlemek, karar vermek, sonucu izlemek. “Söyleseydin yapardım” cümlesi tam burada doğar: Fiziksel iş paylaşılmış, yönetim yükü paylaşılmamış olabilir. Bu bir düşünme aracı, ama dikkat de zaman kadar kıt bir kaynak."],[80,"İkinci vardiya","Sonuçlara göre eve dönmek senin için ikinci bir çalışma gününün başlaması gibi. Arlie Hochschild ve Anne Machung’un kalıcı hâle getirdiği kavramın adı bu: ikinci vardiya. Günün yirmi dört saati değişmediği için ücretsiz işe ayrılan her fazladan saat dinlenmeden, eğitimden ya da ücretli işten eksilir. Kitabın cümlesiyle: “Ücretsiz olmak ile maliyetsiz olmak aynı şey değildir.” Bu bir teşhis değil, bir düşünme aracı."]],"birim":"Görünmeyen Emek Endeksi"},{"no":13,"slug":"ev-isini-kim-yapiyor","ad":"Ev işini kim yaptığını sanıyor, kim yapıyor?","tur":"cift","bolum":"16","sezon":2,"acilis":"2026-11-02","kanca":"Ayrı ayrı çözün, sonra karşılaştırın: Aynı evde yaşıyorsunuz ama aynı evi mi görüyorsunuz?","sorular":[["Bir şeyin bitmek üzere olduğunu fark edip listeye eklemek:",["Hep aynı kişi","Sırayla ya da birlikte"]],["Faturaları ve son ödeme tarihlerini takip etmek:",["Hep aynı kişi","Sırayla ya da birlikte"]],["Akşam ne yeneceğine karar vermek:",["Hep aynı kişi","Sırayla ya da birlikte"]],["Doğum günlerini hatırlayıp hediyeyi ayarlamak:",["Hep aynı kişi","Sırayla ya da birlikte"]],["Bulaşık makinesini boşaltıp tabakları kaldırmak:",["Hep aynı kişi","Sırayla ya da birlikte"]],["Aile üyelerinin doktor randevularını ayarlamak:",["Hep aynı kişi","Sırayla ya da birlikte"]],["Tatil için seçenekleri araştırmak:",["Hep aynı kişi","Sırayla ya da birlikte"]],["Akrabaları arayıp sormak, ilişkiyi sürdürmek:",["Hep aynı kişi","Sırayla ya da birlikte"]],["Bir tartışmadan sonra ortamı yumuşatmak:",["Hep aynı kişi","Sırayla ya da birlikte"]],["Bir işin gerçekten yapılıp yapılmadığını kontrol etmek:",["Hep aynı kişi","Sırayla ya da birlikte"]]],"seviyeler":[[0,"İki ayrı ev","Aynı evde yaşıyorsunuz ama iş bölümünü çok farklı görüyorsunuz. Kitabın hatırlattığı gibi bir işi “yapmak”, ihtiyacı fark etmekten sonucunu kontrol etmeye uzanan zincirin yalnızca bir halkası olabilir. Biriniz son halkayı görürken diğeriniz bütün zinciri görüyor olabilir. Farklı cevap verdiğiniz maddeler, görünmeyen emeğin tam olarak nerede durduğunu gösteriyor. Algı farkı, işin bir kısmının hiç görünmemesinden doğabilir."],[4,"Yarım harita","Bazı işlerde aynı tabloyu görüyorsunuz, bazılarında görmüyorsunuz. Ayrıştığınız maddeler büyük ihtimalle planlama, hatırlama ve takip gibi kolay gözden kaçan işler. Kitaba göre zihinsel yük iyi yapıldığında sorun çıkmaz, bu yüzden yapılan iş de fark edilmez. Bir soru: “Hep aynı kişi” dediğiniz işlerde, o kişinin kim olduğu konusunda da anlaşıyor musunuz?"],[7,"Ortak harita","Evdeki iş bölümünü büyük ölçüde aynı görüyorsunuz. Bu değerli bir başlangıç: Neyin kimde olduğunu iki kişi aynı biçimde görüyorsa konuşmak da kolaylaşır. Yine de kitabın uyarısı geçerli: Aynı algı, adil dağılım demek değildir. Araştırmalara göre eşitsiz bir dağılım bile taraflarca “normal” ya da “adil” kabul edilebiliyor. Asıl soru, aynı gördüğünüz tablonun ikinize de uygun gelip gelmediği."],[9,"Aynı harita","Neredeyse her işte aynı cevabı verdiniz: Evinizin haritası ikinizin zihninde aynı. Şimdi kitabın daha geniş sorusu ilginçleşiyor: İş bölümü yalnız bugünkü rahatlığı mı paylaştırıyor, yoksa birinizin gelecekteki eğitim, gelir ve boş zaman imkânlarını da değiştiriyor mu? Çok sayıda “hep aynı kişi” cevabınız varsa, bu soru en çok o maddeler için anlamlı."]]},{"no":14,"slug":"cocugun-maliyeti","ad":"Bir çocuğun gerçek maliyeti: 6 iddia","tur":"mit","bolum":"17","sezon":2,"acilis":"2026-11-05","kanca":"Bebek bezi faturada görünür ama bir çocuğun asıl maliyeti başka yerlerde saklanır.","sorular":[["Bir çocuğun doğumdan yetişkinliğe kadar maliyeti için her yerde geçerli tek bir rakam vardır.",false,"Yanlış. Kitaba göre maliyet ülkeye, gelir grubuna, kamu hizmetlerinin kapsamına ve ailenin seçtiği yaşam standardına göre büyük ölçüde değişir. Tek rakamlar ancak belirli ülke, yıl ve varsayımlar altında anlam taşır."],["Bir çocuğun en büyük maliyetlerinin bir kısmı aile bütçesinde hiç görünmez.",true,"Doğru. Kitap çocuk maliyetini üç katmanda düşünür: para, zaman ve vazgeçilen alternatifler. Çocuğa ayrılan saatlerde ücretli çalışamamak, eğitim alamamak ya da esnek çalışmak için daha düşük ücret kabul etmek faturada görünmez ama gerçek bir maliyettir."],["Kalabalık ailelerde çocukların daha az eğitim alması, aile büyüklüğünün buna yol açtığını kanıtlar.",false,"Yanlış. Black ve arkadaşlarının (2005) Norveç verileriyle yaptığı çalışmada büyük ailelerdeki çocukların eğitimi ilk bakışta daha düşük görünüyordu. Ama doğum sırası hesaba katılıp ikiz doğumlar kullanıldığında aile büyüklüğünün nedensel etkisi büyük ölçüde ortadan kalktı. Korelasyon nedensellik değildir."],["Yüksek gelirli ülkelerde “gelir arttıkça daha az çocuk” ilişkisi zayıfladı, bazı yerlerde tersine döndü.",true,"Doğru. Doepke ve arkadaşlarının (2023) değerlendirmesine göre doğurganlık ekonomisi “yeni bir döneme” girdi. Kadınların işgücüne katılımının yüksek olduğu kimi ülkeler görece yüksek doğurganlık gösterebiliyor. Belirleyici olan, kariyer ile aileyi birlikte sürdürmenin ne kadar mümkün olduğu."],["Doğum yardımı gibi nakit teşvikler doğurganlığı güçlü ve kalıcı biçimde artırır.",false,"Yanlış. Kitabın aktardığı OECD (2024) değerlendirmesine göre ailelere yapılan nakit transferlerin doğurganlık üzerindeki etkisi çoğunlukla yok, küçük ya da geçici. Tek seferlik bir ödeme, yirmi yıl sürebilecek çocuk yetiştirme maliyetinin küçük bir bölümünü karşılar."],["Danimarka’da ilk çocuktan sonra kadınların kazancında, erkeklere kıyasla uzun dönemli yaklaşık yüzde 20’lik bir fark açıldığı bulundu.",true,"Doğru. Kleven ve arkadaşlarının (2019) çalışması bu farka “çocuk cezası” der. Oran Danimarka’ya özgüdür ve başka ülkelere doğrudan taşınamaz. Kitaba göre bu biyolojik bir yasa da değildir: Ücretli izin, çocuk bakımı ve bakımın nasıl paylaşıldığı maliyetin kimde yoğunlaşacağını değiştirebilir."]],"seviyeler":[[0,"Etiket fiyatı","Çocuğun maliyeti hakkındaki inançlarının çoğu, kitabın aktardığı bulgulardan farklı. Şaşırtıcı değil: Maliyetin büyük kısmı faturada değil, zamanda ve vazgeçilen fırsatlarda saklı. Kitabın ilkesi de açık: Bir çocuğun maliyeti hesaplanabilir, ama değeri fiyatlandırılamaz. Bu iki muhasebeyi birbirine karıştırmamak, çocuk ekonomisinin belki de en temel kuralı. Uykusuz bir gece bir fırsat maliyetidir, o gecenin anlamı ise aynı birimle ölçülemez."],[3,"Bütçe okuru","Bazı iddiaları doğru okudun, bazılarında yanıldın. Çocuk ekonomisi tam da bu yüzden zor: Sezgisel olarak güçlü fikirler, veriyle sınanınca her yerde aynı biçimde işlemeyebiliyor. Örneğin kalabalık ailelerle eğitim arasındaki ilişki, ilk bakışta göründüğü kadar basit değil. Kitabın sorusu hâlâ açık: İnsanlar maliyetini bildikleri hâlde neden hayatlarının en büyük yatırımlarından birini karşılıksız yapar?"],[5,"Aile ekonomisti","Çocuk ekonomisini çok iyi okuyorsun: Görünmeyen maliyetleri, korelasyon tuzağını ve teşviklerin sınırını biliyorsun. Şimdi zor soru: Kitaba göre çocuk yetiştirmenin faydaları topluma yayılırken maliyetin önemli bölümünü aile taşıyor. Bu yükün ne kadarı ortak omuzlara düşmeli? Kitap bir sınır da çizer: Toplumsal faydanın varlığı, üreme hakkının bireye ait olduğu gerçeğini ortadan kaldırmaz."]]},{"no":15,"slug":"kiskanclik","ad":"Kıskançlığın koruma mı, sahiplenme mi?","tur":"profil","bolum":"19","sezon":2,"acilis":"2026-11-09","kanca":"Herkes biraz kıskanır, asıl mesele o duyguyla ne yaptığın.","sorular":[["Partnerin, senin tanımadığın bir iş arkadaşıyla sık sık mesajlaşıyor.",[["R","Açık bir kuralımızı çiğnemedikçe sorun etmem"],["D","Belli etmesem de içim burkulur"],["S","Aklıma bir sürü senaryo gelir"],["K","Kim olduğunu ve ne konuştuklarını sorarım"],["T","Ben de birinden söz ederek tepkisini ölçerim"],["G","Merak edersem sorarım, gerisi onun alanı"]]],["Partnerinin telefonu masada, ekranda bir bildirim yandı.",[["R","Bakmam, bir sorun sezersem açıkça konuşurum"],["D","Bakmam ama kimden geldiğini merak ederim"],["S","Çaktırmadan göz atarım, içim rahatlasın"],["K","Şifresini zaten bilirim, ara sıra kontrol ederim"],["T","Ben de kendi telefonumla meşgulmüş gibi yaparım"],["G","Bakmak aklıma bile gelmez"]]],["Kıskançlık sence çoğu zaman neyin işaretidir?",[["R","Bir sınırın aşıldığının"],["D","Ona çok değer verdiğimin"],["S","Bir şeylerin ters gittiğinin"],["K","Ona sahip çıktığımın"],["T","Hâlâ istendiğimin"],["G","Güvenin biraz sarsıldığının"]]],["Partnerin eski sevgilisiyle arkadaş kalmış.",[["R","Konuştuğumuz sınırlar içindeyse sorun yok"],["D","Kabul ederim ama bir yanım hep tetikte"],["S","Aralarında hâlâ bir şey olduğunu düşünürüm"],["K","Görüşmelerini azaltmasını isterim"],["T","Ben de eski sevgilimden söz etmeye başlarım"],["G","Geçmiş onun geçmişi, ben bugüne bakarım"]]],["Partnerin bir akşam arkadaşlarıyla dışarıda ve söylediğinden geç kaldı.",[["R","Haber vermeden çok gecikirse ararım"],["D","Özlerim, biraz da yalnız hissederim"],["S","Her geçen dakika aklımdan başka şeyler geçer"],["K","Konumunu benimle paylaşmasını isterim"],["T","Bir dahaki sefere ben de geç kalırım"],["G","Keyfine bakarım, gelince anlatır"]]],["Hangi cümle sana daha yakın?",[["R","Kurallar konuşulur, çiğnenince hesabı sorulur."],["D","Seven, kaybetmekten korkar."],["S","Hiç belli olmaz, tedbirli olmak lazım."],["K","Sevdiğin insanın nerede olduğunu bilmek hakkındır."],["T","Biraz kıskançlık ilişkiye tuz biber olur."],["G","Güven, kontrolden daha güçlü bir bağdır."]]]],"sonuclar":{"R":["Sınır bekçisi","Sen kıskançlığı bir alarm gibi kullanıyorsun: Açık bir sınır aşılırsa çalar, aşılmazsa susar. Kitap bunu reaktif kıskançlık diye ayırır: Gerçek ve açık bir ihlale verilen tepki, kanıt olmadan sürekli tehdit arayan kıskançlıktan farklıdır. Senin riskin şurada: Neyin ihlal sayılacağı kültürden kültüre, ilişkiden ilişkiye değişir. Konuşulmamış bir sınıra tepki verdiğinde, karşı taraf o kuralı ilk kez o an öğreniyor olabilir.","19"],"D":["Kaybetme korkusu","Sen kıskançlığı içinde yaşıyorsun: burukluk, özlem, biraz da kaygı. Bu duygu değer verdiğin bir ilişkiyi kaybetme korkusundan doğuyor. Pfeiffer ve Wong’un çalışmasında duygusal kıskançlık ile romantik sevgi arasında belirli pozitif ilişkiler bulunmuştu. Ama kitap bir sınır çizer: Kıskançlığın varlığı ilişkinin değerli olduğunu gösterebilir, yoğunluğu ise sevginin miktarını ölçmez. Kitabın sorusu tam sana göre: Neyi kaybetmekten korkuyoruz?","19"],"S":["Sürekli alarm","Senin kıskançlığın daha çok zihninde dolaşıyor: senaryolar, ihtimaller, ipuçları. Kitap buna bilişsel kıskançlık der ve önemli bir bulgu aktarır: Sürekli şüphe ve kuşku, sevgiyle aynı yönde hareket etmez. Dijital çağ bu yakıtı bol bol üretir, bir kalp emojisi arkadaşlık da olabilir, flört de. Kitabın benzetmesiyle kıskançlık ilişkinin alarmıdır ama alarmın çalması yangın olduğunu kanıtlamaz.","19"],"K":["Sahiplenme","Cevapların, kıskançlığın duygudan davranışa geçtiği yeri gösteriyor: sormak, kontrol etmek, sınırlamak. Bu davranışların kaynağı kaybetme korkusu olabilir. Ama kitaba göre kaynağı açıklamak davranışı haklı çıkarmaz. Ama kitap açık konuşur: “Bir duygunun anlaşılabilir olması, o duyguyla yapılan her davranışı kabul edilebilir hale getirmez.” Kontrol, karşı tarafın davranış alanını daraltmaya başlar. Kitabın en net fikirlerinden biri de şu: Sevgi bağlılık yaratabilir, ama mülkiyet hakkı yaratmaz.","19"],"T":["Kıskandıran","Sen ilgiyi ölçmek için bazen terazinin öbür kefesine bir rakip koyuyorsun. Kitap bunu partneri ilişkide tutmaya yönelik stratejiler arasında anlatır. İspanya’daki bir çalışmada daha düşük ilişki bağlılığı bildirenlerin bilinçli kıskançlık yaratmayı daha sık kullandığı bulunmuştu. Kısa vadede ilgi artabilir. Ama kitabın sinyal kuralı burada da geçerli: Bir sinyal göndericinin niyetini değil, alıcının yorumladığı anlamı taşır.","19"],"G":["Güvenli liman","Sen kıskançlığı nadiren hissediyorsun, hissettiğinde de sormayı tercih ediyorsun. Kitaba göre güven arttıkça aynı tehdidin algılanışı azalabilir. Güvenin bir bölümü doğrulanabilir bilgiden, bir bölümü de belirsizliğe rağmen partnerin sınırlarına saygı göstermekten oluşur. Tek bir risk var: Romantik kültür kıskançlığı sevginin işareti sayar, bu yüzden hiç kıskanmayan biri bazen ilgisiz sanılabilir. Rahatlık ile ilgisizlik aynı şey değildir.","24"]}},{"no":16,"slug":"cok-eslilik-mitleri","ad":"Çok eşlilik tarihi: Mit mi, gerçek mi?","tur":"mit","bolum":"18","sezon":2,"acilis":"2026-11-12","kanca":"Çok eşlilik tarihi, çoğumuzun sandığından çok daha şaşırtıcı bir hikâye anlatıyor.","sorular":[["İncelenen insan toplumlarının büyük çoğunluğu, erkeklerin birden fazla eş edinmesine en azından izin vermiştir.",true,"Doğru. Henrich ve arkadaşlarının (2012) etnografik kayıtları değerlendiren çalışmasına göre bu oran yaklaşık yüzde 85."],["Bu yüzden tarih boyunca erkeklerin çoğu birden fazla kadınla evliydi.",false,"Yanlış. Bir toplumun polijiniye izin vermesi ile nüfusun çoğunun öyle yaşaması aynı şey değildir. Kitaba göre çok eşli evlilik çoğu toplumda toprak, hayvan, gelir, statü ya da siyasi güce sahip belirli erkeklerin erişebildiği bir düzenlemeydi."],["Bugün dünya nüfusunun yaklaşık yüzde 2’si poligamik hanelerde yaşıyor.",true,"Doğru. Bu, Pew Research Center’ın 130 ülke ve bölgeyi kapsayan araştırmasının tahmini. Oran Batı ve Orta Afrika’nın bazı bölgelerinde çok daha yüksek. Bugünkü dünya, etnografik kayıtların ima ettiğinden çok daha tek eşli."],["Bir kadının birden fazla erkekle evli olduğu poliandri, insan toplumlarında hiç görülmemiştir.",false,"Yanlış. Poliandri çok daha seyrek ama gerçek. Starkweather ve Hames (2012), poliandriye izin veren 53 toplum belirledi ve bu evlilik biçiminin sanıldığından daha geniş bir coğrafyaya yayıldığını gösterdi."],["Himalaya’daki kardeş poliandrisi, kıt tarım arazisinin kuşaktan kuşağa bölünmesini önleyebilir.",true,"Doğru. Kitaba göre birkaç erkek kardeşin aynı kadınla evlenmesi, bölünebilir arazinin kıt olduğu yerlerde aile mülkünün her kuşakta daha küçük parçalara ayrılmasını önleyebilir. Ama kitap bütün poliandri örneklerini bu tek formüle sıkıştırmamak gerektiğini de hatırlatır."],["Polijin hanelerdeki kadınlar her konuda, tek eşli hanelerdeki kadınlardan daha az kontrole sahiptir.",false,"Yanlış, en azından her yerde değil. Burkina Faso’daki polijin haneleri inceleyen Eissler ve arkadaşları (2025), karar almanın genellikle hiyerarşik kaldığını ama bazı hanelerde kadınların kendi kazançları üzerinde tek eşli hanelerdekinden daha fazla kontrol sürdürebildiğini buldu."]],"seviyeler":[[0,"Efsane okuru","Çok eşlilik hakkındaki inançlarının çoğu, kitabın aktardığı bulgulardan farklı. En şaşırtıcı ayrım şu: Bir ilişki biçiminin çok sayıda toplumda meşru görülmesi, insanların çoğunun öyle yaşadığı anlamına gelmez. Bugünkü dünya, etnografik kayıtların ima ettiğinden çok daha tek eşli. Kitaba göre çok eşlilik, servet ve statü dağılımının aile yapısına çevrildiği bir kurum olarak da incelenebilir."],[3,"Tarih meraklısı","Bazı iddiaları doğru okudun, bazılarında yanıldın. Çok eşlilik, hakkında en çok kalıp yargı dolaşan konulardan biri. Kitabın bu bölümdeki temel dersi işine yarayabilir: Aile biçimleri servetten, mirastan ve toprak kıtlığından bağımsız değildir. Nadir kurumların bile tek bir ekonomik nedeni yoktur. Kitabın ifadesiyle insan doğasının ayırt edici özelliklerinden biri, farklı ilişki kurumlarını kurabilecek kadar esnek olmasıdır."],[5,"Saha antropoloğu","Çok eşlilik tarihini çok iyi okuyorsun. Şimdi kitabın sorduğu daha zor soru: Bir yapının adil olup olmadığını anlamak için kaç kişi olduğuna değil, kimin karar verebildiğine, kaynakların nasıl paylaşıldığına ve isteyenin ilişkiden çıkıp çıkamadığına bakmak gerekmez mi? Kitaba göre hukuki izin ile tarafların eşit pazarlık gücü farklı kavramlardır. Ölçü “kaç kişi?” sorusuyla bitmez."]]},{"no":17,"slug":"iliski-sozlesmesi","ad":"İlişkin bir sözleşme olsaydı hangi maddesi bozuk olurdu?","tur":"senaryo","bolum":"15","sezon":2,"acilis":"2026-11-16","kanca":"Hiçbir ilişki yazılı sözleşmeyle kurulmaz ama her birinin görünmez maddeleri vardır.","sorular":[["Akşam bir tartışma başladı. Büyük ihtimalle konu ne?",[["K","Sorulmadan yapılan bir harcama"],["E","Evdeki işlerin hep aynı kişide kalması"],["G","Söylenenle yapılanın tutmaması"],["B","Birlikte vakit geçirmeyi unutmamız"],["C","“Böyle giderse biter” cümlesinin kurulması"]]],["İlişkinize bir sözleşme yazılsa ilk hangi maddeyi eklemek isterdin?",[["K","Paranın nasıl bölüşüleceği"],["E","Ev işlerinin ve takibinin kimde olduğu"],["G","Önemli hiçbir şeyin saklanmayacağı"],["B","Haftada bir akşamın yalnız ikimize ait olduğu"],["C","İsteyen tarafın onurlu biçimde ayrılabileceği"]]],["Partnerin bir hafta iş seyahatine çıktı. Ne fark edersin?",[["K","Harcamaları kimin karşıladığını daha net görürüm"],["E","Evdeki her şeyi zaten ben takip ediyormuşum"],["G","Nerede, kiminle olduğunu merak ettiğimi"],["B","Birlikteyken de pek konuşmadığımızı"],["C","Tek başıma da gayet idare edebildiğimi"]]],["Bir arkadaşın ilişkini anlatmanı istedi. Hangi cümleyi kurma ihtimalin yüksek?",[["K","“Para konusu bizde hep biraz gergin.”"],["E","“Ben hatırlatmazsam hiçbir şey yapılmıyor.”"],["G","“Bazen bir şey sakladığını hissediyorum.”"],["B","“İyiyiz ama ev arkadaşı gibiyiz.”"],["C","“Ayrılmak istesem bile kolay olmazdı.”"]]],["Yıldönümünüz yaklaşıyor. Aklından ilk ne geçer?",[["K","Bütçemiz ne kadar, kim ödeyecek?"],["E","Planlamayı yine ben mi yapacağım?"],["G","Verdiği sözü bu kez tutacak mı?"],["B","En son ne zaman baş başa kaldık?"],["C","Gerçekten istediğimiz için mi birlikteyiz?"]]],["Hangi cümle ilişkine en çok lazım?",[["K","“Bizim paramız” gerçekten bizim olsun."],["E","Görünmeyen işler de görülsün."],["G","Söylenen yapılsın, saklanan olmasın."],["B","Rutinin içinde de birbirimizi bulalım."],["C","Kalmak zorunluluk değil, seçim olsun."]]]],"sonuclar":{"K":["Bozuk madde: Kasa","Senin ilişkinde en çok gıcırdayan madde para. Sorun çoğu zaman paranın miktarı değil, nasıl paylaşıldığı. Kitap haneyi tek bir karar verici gibi düşünmenin yanıltıcı olduğunu söyler: Eşlerin tercihleri kısmen ortak ama tamamen aynı değildir. “Bizim paramız” demek kolaydır, nasıl bölündüğü ayrı bir sorudur. Kitaba göre evliliğin kazancı yalnız pastanın büyüklüğüyle değerlendirilemez, pastanın nasıl bölündüğünü de bilmek gerekir.","15"],"E":["Bozuk madde: Emek","Senin ilişkinde zorlanan madde, kimsenin yazmadığı işler: fark etmek, hatırlamak, takip etmek. Kitap bunu zihinsel yük diye anlatır. “Söyleseydin yapardım” diyen kişi gerçekten söylenen her işi yapıyor olabilir. Ama ne yapılacağını fark etmek, görevi tanımlamak ve takip etmek hep diğerindeyse fiziksel iş paylaşılmış, yönetim yükü paylaşılmamış olabilir. Bu madde yazılmadıkça emeğin bedeli hep aynı hanede birikir.","16"],"G":["Bozuk madde: Güven","Senin ilişkinde zorlanan madde, hiçbir sözleşmeye tam yazılamayan madde: güven. Kitap ilişkiyi eksik bir sözleşme olarak anlatır. Beş yıl sonra çıkacak hastalığı, iş kaybını, krizi önceden yazamayız. Yazılamayan her durumda iki kişi birbirinin iyi niyetine ve geçmiş davranışlarına dayanır. Kitaba göre güven sözleşmenin alternatifi değil, sözleşmenin ulaşamadığı yerlerde birlikte yaşamanın koşuludur ve hammaddesi tekrar eden tutarlılıktır.","24"],"B":["Bozuk madde: Bakım","Senin ilişkinde zorlanan madde kriz değil, ihmal. Faturalar ödeniyor, işler dönüyor ama ilişkinin kendisine pek sıra gelmiyor. Kitap bu tehlikeyi açıkça adlandırır: Ortak hayat giderek yalnız lojistik bir şirkete dönüşebilir. Ogolsky ve Bowers’ın 35 çalışmayı kapsayan meta-analizinde ilişki süresi, bakım davranışlarıyla sürekli pozitif ilişki göstermiyordu. Yani uzun süre birlikte olmak, ilişkinin iyi korunduğunun kanıtı değildir.","25"],"C":["Bozuk madde: Çıkış","Senin ilişkinde zorlanan madde, en az konuşulan madde: çıkış. Kalmanın bir seçim mi, bir zorunluluk mu olduğu bulanıklaşmış olabilir. Kitap bağlılık ile hapis arasında temel bir fark görür: Ayrılık imkânsızlaştığında yatırım korunur ama kötü ilişkiden çıkış da engellenir. Öte yandan sürekli bir ayrılık tehdidi de manipülasyon olabilir. Kitabın gözlemi: “Gitme imkânının artması, gitme arzusunun artmasıyla aynı şey değildir.”","15"]}},{"no":18,"slug":"bosanmanin-faturasi","ad":"Boşanmanın gerçek faturası","tur":"mit","bolum":"22","sezon":2,"acilis":"2026-11-19","kanca":"Boşanmanın bedeli mahkeme kapısında başlamaz, orada da bitmez.","sorular":[["Ayrılan bir çiftin toplam geliri hiç değişmese bile kişi başına yaşam maliyeti artabilir.",true,"Doğru. Tek mutfak, tek internet bağlantısı, tek oturma odası iki haneye bölününce ölçek ekonomisi kaybolur. Kitabın deyişiyle insan eşinden ayrılırken aynı zamanda hane ölçeği ekonomisinden de ayrılır."],["Boşanmayı tek tarafın başlatabilmesine izin veren yasalar, boşanmaları kalıcı olarak büyük ölçüde artırdı.",false,"Yanlış. Justin Wolfers’ın (2006) ABD eyaletlerini yeniden inceleyen çalışmasına göre reformlardan sonra geçici bir artış görüldü, ama bu artışın büyük bölümü yaklaşık on yıl içinde tersine döndü."],["“Evliliklerin yarısı boşanmayla biter” her ülke ve kuşak için geçerli bir gerçektir.",false,"Yanlış. Kitaba göre bu tür tek oranlar evrensel gerçekler değildir. Yıllık boşanma sayısını nüfusa bölmek, mevcut evliliklerin ne kadarının sonunda boşanacağını söylemez. Boşanmayı anlamak için payda en az pay kadar önemlidir."],["ABD’de 50 yaş üstü boşanmalarda hem kadınların hem erkeklerin serveti yaklaşık yarıya geriledi.",true,"Doğru. Lin ve Brown’ın (2021) çalışmasında servet her iki grupta yaklaşık yarıya düştü, yaşam standardı göstergesi ise kadınlarda yaklaşık yüzde 45, erkeklerde yaklaşık yüzde 21 geriledi. Bunlar belirli bir ülke, dönem ve yaş grubunun sonuçları, evrensel oranlar değil."],["Boşanma oranının yükselmesi, evliliklerin kalitesinin düştüğünü gösterir.",false,"Yanlış, en azından her zaman değil. Kitaba göre ekonomik bağımlılığın yüksek olduğu dönemlerde bazı kötü evlilikler istatistiklere hiç girmemiş olabilir, çünkü taraflardan biri ayrılmayı göze alamıyordu. Çıkış maliyeti düşünce bu evlilikler görünür hâle gelir (Stevenson ve Wolfers, 2006)."],["Almanya’daki uzun dönemli bir çalışmada boşanmanın gelir kaybı ve yoksulluk riski kadınlarda daha büyük ve kalıcı bulundu.",true,"Doğru. Thomas Leopold’un (2018) çalışmasında erkekler yaşam doyumu gibi bazı öznel göstergelerde daha keskin ama kısa dönemli düşüşler yaşadı. Kadınların hane geliri kaybı ve yoksulluk riskindeki artış ise daha büyük ve kalıcıydı. “Kim için daha kötü” sorusunun cevabı, hangi sonuçtan söz edildiğine bağlı."]],"seviyeler":[[0,"Kolay hesap","Boşanmanın ekonomisi hakkındaki inançlarının çoğu, kitabın aktardığı bulgulardan farklı. Belki de en önemlisi şu: Boşanmanın ilk ekonomik şoku romantik değildir ama gerçektir. Daha önce tek hanenin taşıdığı sabit maliyetler iki haneye dağılır. Kira, ısınma, mobilya ve taşınma aynı geliri iki kez zorlar. Toplam gelir değişmese bile kişi başına yaşam maliyeti artabilir."],[3,"Yarım fatura","Bazı kalemleri doğru okudun, bazılarını gözden kaçırdın. Bu çok doğal, çünkü boşanma hakkında en çok tekrarlanan cümlelerin bir kısmı veriyle uyuşmuyor. Boşanma istatistikleri tam da bu yüzden yanıltıcı olabilir: Tek bir oran, kimin hangi bedeli ne kadar süre ödediğini göstermez. Kitaba göre boşanmanın sonucu, hangi evlilikten çıkıldığına ve sonrasında hangi hayata girildiğine bağlıdır. Kitabın sorusu hâlâ geçerli: Kalmak ne zaman gitmekten pahalıdır?"],[5,"Tam döküm","Boşanmanın faturasını çok iyi okuyorsun: ölçek kaybını, yasa etkisinin sınırını ve kimin neyi kaybettiğini biliyorsun. Kitabın en zor sorusu şimdi senin: Bu evliliğin sürmesi ve sona ermesi hâlinde kim hangi maliyetleri taşıyor? Kitaba göre boşanmanın iyi olması acısız olması demek değildir. Daha anlamlı ölçüt, kaçınılmaz maliyetlerin gereksiz çatışmayla büyütülüp büyütülmediğidir."]]},{"no":19,"slug":"evliligin-yuzyili","ad":"Evliliğin hangi yüzyıldan?","tur":"nesil","bolum":"29","sezon":2,"acilis":"2026-11-23","kanca":"Aşkla evlenmek sandığından daha yeni bir fikir, peki senin evlilik hayalin hangi döneme ait?","sorular":[["Eşini seçerken en çok neyin sözü geçmeli?",[["K","Ailemin, çünkü evlilik iki aileyi birleştirir"],["R","Kalbimin, aşk yoksa evlilik de yok"],["U","Kimin neyi üstleneceğinin netliğinin"],["A","En iyi arkadaşım olabilmesinin"],["B","Kendimi hazır hissettiğim zamanın"]]],["Evlilik hayatın neresinde durur?",[["K","Yetişkinliğin ve aile düzeninin başında"],["R","Büyük bir aşkın doğal sonunda"],["U","Ev kurulup roller paylaşıldığında"],["A","Bir arkadaşlığın ömür boyu sürdüğü yerde"],["B","Her şey yoluna girdikten sonra, en tepede"]]],["Evde para ve iş nasıl bölünmeli?",[["K","Geleneğin ve ailenin öngördüğü gibi"],["R","Aşk varsa gerisi kendiliğinden çözülür"],["U","Biri dışarıda kazanır, öbürü evi çevirir"],["A","Birlikte karar verir, birlikte yaparız"],["B","Her şeyi konuşur, kendi düzenimizi kurarız"]]],["İyi bir eşin en önemli özelliği ne?",[["K","Ailesine ve sorumluluklarına bağlı olması"],["R","Beni ilk günkü gibi heyecanlandırması"],["U","Üstlendiği işi aksatmadan yapması"],["A","Onunla saatlerce konuşabilmem"],["B","Kişisel gelişimimi desteklemesi"]]],["Düğün senin için ne demek?",[["K","İki ailenin ve çevrenin onayı"],["R","Aşkımızın herkese ilanı"],["U","Yeni bir hanenin kuruluş günü"],["A","En yakınlarımızla güzel bir kutlama"],["B","Birlikte başardıklarımızın taçlandığı gün"]]],["Evlilikte en büyük hayal kırıklığı ne olurdu?",[["K","Aileye ve çevreye mahcup olmak"],["R","Aşkın zamanla sönüp gitmesi"],["U","Birinin üstüne düşeni yapmaması"],["A","Birbirimize anlatacak bir şey kalmaması"],["B","İlişkinin beni büyütmemesi"]]]],"sonuclar":{"K":["Yüzyıllar boyu: Kurumsal evlilik","Senin evlilik anlayışın çok eski bir köke dayanıyor. Kitaba göre tarihsel evlilik mülkiyetin aktarılmasını, çocukların soy hattına yerleşmesini, bakımın örgütlenmesini, üretim emeğinin paylaşılmasını ve aileler arası ittifakı aynı kurumda topluyordu. Romantik sevgi bulunabilirdi ama eş seçiminin temel kaynağı olmak zorunda değildi. Kitabın uyarısı: Böyle evliliklerin uzun sürmesi yüksek duygusal doyumun kanıtı değildir, çıkış seçeneği yoksa çift zaten birlikte kalır.","29"],"R":["18. ve 19. yüzyıl: Romantik ideal","Senin evlilik anlayışının merkezinde aşk var: Sevdiğinle evlenmek ve başka bir gerekçeye ihtiyaç duymamak. Kitap, on sekizinci ve on dokuzuncu yüzyıllarda biçimlenen romantik ideallerden söz eder. Stephanie Coontz’un “aşk devrimi” dediği dönüşüm de aile çıkarı için sevilmeyen biriyle evlenmenin meşruiyetini zayıflattı ve evlilikten duygusal tatmin beklemeyi normalleştirdi. Bedeli şu: Evlilik için yeni bir başarı ölçütü doğdu, “Onunla mutlu muyum?”","28"],"U":["20. yüzyıl ortası: İş bölümü evliliği","Senin evlilik anlayışın net bir iş bölümüne dayanıyor: Biri dışarıda kazanır, öbürü evi ve bakımı yönetir. Kitaba göre Gary Becker’ın uzmanlaşma modeli, yirminci yüzyılın ortasındaki birçok hanenin gerçek yapısını iyi betimleyen unsurlar taşıyordu. Ama betimleme ile değişmez yasa aynı şey değildir. Eğitim, ücretli çalışma ve piyasadan alınabilen hizmetler bu modelin getirisini değiştirdi. Uzmanlaşmanın uzun dönemli maliyeti de tek kişide birikebilir.","15"],"A":["20. yüzyıl: Arkadaşlık evliliği","Senin için eş her şeyden önce en yakın arkadaş. Kitap, sosyolog Andrew Cherlin’in şemasını aktarır: Yirminci yüzyıl içinde arkadaşlık temelli evlilik öne çıktı ve sevgi ile eşler arası arkadaşlık evliliğin merkezine yerleşti. Evlilik artık yalnız görevlerin yerine getirildiği bir birliktelik değildi. Bu model güçlü bir yakınlık vaat eder. Riski de buradan doğar: Konuşacak şey azaldığında evliliği taşıyan ana direk de zayıflar.","29"],"B":["Bugün: Kapak taşı evlilik","Senin evlilik anlayışın tam bugünün: önce iş, birikim, ev ve kendini tanımak, sonra nikâh. Sosyoloji buna temel taşı ile kapak taşı ayrımı der. Eski modelde evlilik hayatın temel taşıydı, yeni modelde kurulmuş hayatın üzerine konan kapak taşı. OECD ortalamasında ilk evlilik yaşı 2021’de kadınlarda yaklaşık 31, erkeklerde yaklaşık 33,4’e yükseldi. Bedeli: Giriş çıtası yükseldikçe ekonomik olarak kırılgan olanlar nikâha daha geç ulaşabilir.","29"]}},{"no":20,"slug":"ayni-evlilik","ad":"İkiniz aynı evliliği mi hayal ediyorsunuz?","tur":"cift","bolum":"15","sezon":2,"acilis":"2026-11-26","kanca":"Ayrı ayrı çözün, sonra karşılaştırın: “Evet” derken aynı evliliğe mi evet diyorsunuz?","sorular":[["Evlilik:",["Hayatı birlikte kurmanın başlangıcı","Kurulmuş bir hayatın tacı"]],["Nikâh en çok:",["Hukuki bir güvence","Bağlılığın herkese ilanı"]],["Evliliğin asıl kazancı:",["İşleri ve yükleri bölüşmek","Sevdiğimiz şeyleri birlikte yapmak"]],["Para:",["Tek kasa","Ortak bütçe, ayrı hesaplar"]],["Kariyerler:",["Gerekirse biri öne çıkar, öbürü destekler","İkisi de aynı ağırlıkta yürür"]],["Evlenmeden önce:",["Ekonomik olarak hazır olmalıyız","Hazırlığı evlenince birlikte yaparız"]],["Nikâhsız birlikte yaşamak:",["Evliliğe bir hazırlık","Kendi başına bir seçenek"]],["Boş zaman:",["Çoğunu birlikte geçiririz","Herkesin kendi alanı da olur"]],["Eşimden en çok beklediğim:",["Hayatın yükünü paylaşması","Kendimi geliştirmemi desteklemesi"]],["Düğün:",["Kalabalık ve görkemli","Küçük ve sade"]]],"seviyeler":[[0,"İki ayrı evlilik","Aynı kurumdan çok farklı şeyler bekliyorsunuz. Kitap bunu kendi başına bir sorun saymaz: Biri evliliği iki bağımsız insanın ortaklığı, öbürü boş zamanın neredeyse tamamının birlikte geçtiği bir birliktelik olarak görebilir. Kitaba göre sorun modellerin kendisi değil, tarafların aynı kurumdan farklı şey beklemesi olabilir. Farklı cevap verdiğiniz maddeler, konuşulmamış beklentilerin haritası."],[4,"Aynı bina, farklı planlar","Bazı temel konularda aynı evliliği hayal ediyorsunuz, bazılarında yollarınız ayrılıyor. Kitaba göre modern evlilikte gelenek daha az cevap verdikçe daha fazla müzakere gerekir: Çift kendi kurumunu kendisi tasarlamak zorunda kalır. Ayrıştığınız maddeler, o tasarımın henüz çizilmemiş kısımları. Kitabın deyişiyle özgürlük artar, koordinasyon ihtiyacı da artabilir. Farklı cevaplar bir uyumsuzluk kanıtı değil, konuşulacak gündemin listesi."],[7,"Ortak plan","Evlilikten büyük ölçüde aynı şeyleri bekliyorsunuz. Kitabın gözlemiyle devlet herkese aynı nikâhı verir, çiftler o nikâha farklı hikâyeler yükler. Sizin hikâyeleriniz çoğu yerde örtüşüyor. Ayrıldığınız birkaç madde varsa, bunlar büyük ihtimalle hayat değiştikçe yeniden konuşulacak olanlar. Ortak bir plan, değişmeyen bir plan demek değildir. İş, çocuk ya da şehir değiştiğinde aynı sorular yeniden masaya gelir."],[9,"Aynı hikâye","Neredeyse her maddede aynı evliliği hayal ediyorsunuz. Kitaba göre modern evliliğin ayırt edici özelliği, anlamını giderek çiftlerin kendilerinin yazması. Siz aynı satırları yazıyorsunuz. Kitaptan tek bir not: Çiftler eşitlikçi bir idealle başlayabilir, ama çocuk, ücret farkı ve iş hayatının beklentileri onları zamanla daha geleneksel bir düzene sürükleyebilir. Hayal aynı, hayat değişebilir."]]},{"no":21,"slug":"beklenti-enflasyonu","ad":"Beklenti Enflasyonu Endeksin kaç?","tur":"hesap","bolum":"28","sezon":3,"acilis":"2026-11-30","kanca":"Sevgili, en iyi arkadaş, sırdaş, kariyer danışmanı: Bir insana kaç iş tanımı sığar?","sorular":[["Sevgili, en iyi arkadaş, sırdaş, ev arkadaşı, tatil arkadaşı, kriz desteği, kariyer danışmanı, kişisel gelişim destekçisi… Bu rollerden kaçını partnerinden beklersin?",[[0,"Üç dört tanesini, gerisi için hayatımda başka insanlar var"],[1,"Yaklaşık yarısını"],[2,"Çoğunu"],[3,"Hepsini, partner dediğin zaten bu"]]],["Uzun süredir seni zorlayan bir sorunla boğuşuyorsun. Destek için kime yaslanırsın?",[[0,"Partnerime, arkadaşlarıma, gerekirse bir uzmana"],[1,"Önce partnerime, sonra başkalarına da"],[2,"Çoğunlukla partnerime, başkasına pek anlatmam"],[3,"Yalnızca partnerime, beni ondan iyi kimse anlayamaz"]]],["Doğum günün yaklaşıyor. Ne istediğini partnerine söyler misin?",[[0,"Açıkça söylerim, tahmin oyununu sevmem"],[1,"İpucu veririm, gerisi ona kalmış"],[2,"Söylemem, beni tanıyorsa bilir"],[3,"Söylemek zorunda kalırsam hediyenin anlamı kalmaz"]]],["Yıllar sonra partnerinden ne beklersin?",[[0,"Güven versin, heyecanı da arada birlikte yaratırız"],[1,"Güven versin, ara sıra da beni şaşırtsın"],[2,"Hem hep güven versin hem hep heyecanlandırsın"],[3,"İlk günkü heyecan hiç sönmesin, sönerse bir şey yanlıştır"]]],["İdeal partner listende kaç madde “olmazsa olmaz”?",[[0,"Birkaç tane: saygı, dürüstlük, güven gibi"],[1,"Beş altı tane"],[2,"Listenin çoğu"],[3,"Hepsi, birinden vazgeçersem razı olmuşum demektir"]]],["Hangi cümle sana daha yakın?",[[0,"“Seninle hayatımın bazı alanları daha zengin.”"],[1,"“Sen benim en yakın insanımsın.”"],[2,"“Sen benim her şeyimsin.”"],[3,"“Sen beni tamamlıyorsun.”"]]]],"seviyeler":[[0,"Fiyat istikrarı","Partnerinden beklediklerini sıraya koymuşsun: Bir çekirdek var, gerisi hayatındaki başka insanlarla paylaşılıyor. Kitap bunu beklentiyi düşürmek değil, dağıtmak olarak anlatır: Güçlü romantik bağ ile zengin sosyal ağ birbirinin rakibi değildir. Ama düşük endeks “az iste” demek değildir. Kitaba göre şiddetsizlik, rıza, temel saygı ve dürüstlük gibi beklentiler ne dağıtılabilir ne düşürülmelidir. Bu bir ölçüm değil, bir düşünme aracıdır."],[26,"Ilımlı enflasyon","Beklentilerin yüksek ama çoğu makul. Kitap standart sahibi olmanın sorun olmadığını söyler: Standartlar kötü eşleşmeleri fark etmemize yardım eder. Asıl çizgi standart ile kusursuzluk talebi arasındadır ve listende birkaç madde bu çizgiye yaklaşıyor olabilir. Kitabın sorduğu sorular işine yarayabilir: “Bu beklenti partner tarafından biliniyor mu, karşılıklı mı, kaynaklarımızla uyumlu mu ve gerçekten benim için vazgeçilmez mi?”"],[51,"Yüksek enflasyon","Partnerinin iş tanımı uzun: sevgili, sırdaş, kriz desteği, belki biraz da danışman. Kitap bunu bir iş ilanına benzetir: Aynı kişiden bütün görevleri eşit iyilikte yapmasını bekleriz. Her beklenti tek başına makul olabilir, toplam paket ise ağırlaşır. Bedeli şu: Tek kişiden her şeyi beklediğinde, onun yetersiz kaldığı her alan bütün ilişkinin başarısızlığı gibi görünebilir. Kitaba göre partner, profesyonel desteğin yerini almak zorunda da değildir."],[76,"Hiperenflasyon","Senin gözünde partner, her ihtiyacın tek tedarikçisi gibi. Kitap Finkel ve arkadaşlarının benzetmesini aktarır: Dağın yükseklerinde manzara daha etkileyicidir, fakat oksijen daha azdır. Bu kadar yüksek beklenti ancak ilişkiye o düzeyde zaman ve enerji ayrıldığında karşılanabilir. Kitap “beklentini düşür” demez, beklenti ile kaynak arasındaki uyuma bakar. Kitabın sorusu: “Partnerimden istediğim şey gerçekten ilişkim için temel mi?”"]],"birim":"Beklenti Enflasyonu Endeksi"},{"no":22,"slug":"iliski-getirisi","ad":"İlişki Yatırım Getirisi hesaplayıcı","tur":"hesap","bolum":"25","sezon":3,"acilis":"2026-12-03","kanca":"Para yatırmadın ama zaman, emek ve dikkat yatırdın, peki karşılığında ne birikiyor?","sorular":[["İyi bir haber aldın: bir terfi, bir kabul, bir başarı. Partnerinin tepkisi genellikle nasıl olur?",[[3,"Sevinir, ayrıntıları sorar, kutlamak ister"],[2,"İçtenlikle tebrik eder, sonra gündem değişir"],[1,"“Güzel” der ama aklı başka yerdedir"],[0,"Hemen olası sorunları ya da eksikleri sıralar"]]],["Yaptığın küçük şeyler (haber vermek, bir ayrıntıyı hatırlamak, bir yükü paylaşmak) fark ediliyor mu?",[[3,"Çoğu zaman fark edilir ve dile getirilir"],[2,"Fark edilir ama pek söylenmez"],[1,"Ancak yapmadığımda fark edilir"],[0,"Görünmez kalır, sanki kendiliğinden oluyor"]]],["Kendi hedeflerin (eğitim, sağlık, iş, bir uğraş) açısından bu ilişki seni nereye taşıyor?",[[3,"Olmak istediğim kişiye yaklaştırıyor"],[2,"Destekliyor ama pek bir etkisi yok"],[1,"Hedeflerim ilişkinin gölgesinde kaldı"],[0,"Hedeflerimi “ilişkimiz için” bıraktım"]]],["En son birlikte yeni bir şey (bir yer, bir uğraş, bir deneyim) ne zaman yaptınız?",[[3,"Son birkaç hafta içinde"],[2,"Son birkaç ay içinde"],[1,"Hatırlamakta zorlanıyorum"],[0,"Ortak anılarımızın hepsi eskide kaldı"]]],["Uzun vadede bakınca ilişkide kim ne veriyor?",[[3,"Dönem dönem değişse de denge kuruluyor"],[2,"Biraz dengesiz ama ikimiz de bunu görüyoruz"],[1,"Genellikle aynı taraf veriyor"],[0,"Hep aynı taraf veriyor ve bu konuşulamıyor"]]],["İlişkiye harcanan enerjinin çoğu nereye gidiyor?",[[3,"Yeni şeyler kurmaya, birlikte plan yapmaya"],[2,"Gündelik düzeni sürdürmeye"],[1,"Aynı tartışmaları yatıştırmaya"],[0,"Hasar onarımına, başka şeye enerji kalmıyor"]]]],"seviyeler":[[0,"Uyarı ışığı","Cevapların, ilişkiye harcanan emeğin büyük kısmının onarıma gittiğini ya da verilenin görünmez kaldığını düşündürüyor. Kitap burada bir eşik koyar: Ortak hayatın bilançosu tam denk olmayabilir, fakat sürekli tek tarafa zarar yazıyorsa yatırım metaforu uyarı vermeye başlar. Bu bir hüküm değil, bir düşünme aracı. Kitabın bölüm başındaki sorusu: Hangi yatırımlar ilişkiyi gerçekten besler?"],[26,"Bakım bekleyen hesap","İlişkin işliyor ama getirisi azalıyor gibi. Kitaba göre ilişki sona ermeden önce bazen dramatik bir kriz değil, uzun süreli ihmal yaşanır. Faturalar ödenir, işler yürür, ama ortak hayat giderek bir lojistik şirkete dönüşebilir. Bedeli şu: İlişki işlevini yerine getirirken yakınlık sessizce azalabilir. Kitap çözümü büyük jestlerde değil, yüzlerce kez tekrarlanan küçük davranışlarda arar."],[51,"Düzenli getiri","İlişkin sana değer katıyor: Küçük katkılar görülüyor, denge büyük ölçüde korunuyor. Kitap ilişki bakımını sürekli harcama olarak değil, ortaklığın kullanım değerini koruyan düzenli yatırım olarak anlatır. Bir uyarı var: İlişkinin bazı getirileri kendiliğinden yenilenmez. Yeni ortak deneyim üretilmediğinde bütün hatıralar giderek geçmiş zamana ait hale gelebilir. Yatırım bazen ilişkiye yeni malzeme eklemektir."],[76,"Bileşik getiri","İlişkin hem zor günde bir sigorta hem iyi günde getiriyi çoğaltan bir ortaklık gibi çalışıyor. Kitabın deyişiyle iyi ortak yalnız yükümüzü taşımaya değil, büyümemize de dayanabilen insandır. Yine de yüksek puan bir garanti değildir. Kitaba göre romantik ilişkide en yüksek getirilerin bazıları sayıya çevrilemez. Bu endeks de onları ölçmez, yalnızca üzerine düşünmeye çağırır."]],"birim":"Getiri Endeksi"},{"no":23,"slug":"batik-maliyet","ad":"Batık maliyet: Bitmesi gereken bir ilişkide misin?","tur":"senaryo","bolum":"25","sezon":3,"acilis":"2026-12-07","kanca":"Geçmişe verdiklerin bugünkü kararını ne kadar yönetiyor?","sorular":[["Arkadaşın yedi yıllık ilişkisini anlatıyor: “Mutlu değilim ama bunca yıl verdim.” Ona ne dersin?",[["G","“Yedi yıl az değil, hemen vazgeçme.”"],["S","“Geçen yıllar geçti, onları hesaba katma.”"],["A","“Yılların hangisi bugün hâlâ bir şey taşıyor, ona bak.”"],["Y","“Önümüzdeki yedi yılı nasıl geçirmek istiyorsun?”"]]],["Aylar önce birlikte pahalı bir tatil planladınız ve parasını ödediniz. Şimdi aranız gergin ve tarih yaklaşıyor.",[["G","Para ödendi, gidilir, boşa gitmesin"],["S","Para zaten gitti, kararı hiç etkilememeli"],["A","Geri alınabilen bir kısım var mı, önce ona bakarım"],["Y","O haftayı başka nasıl geçirebileceğimi de tartarım"]]],["Bir ilişkinin bitmesine dair en çok neden korkardın?",[["G","Verdiğim her şeyin boşa gitmiş olmasından"],["S","Geçmişe takılıp yeni sayfayı açamamaktan"],["A","Ortak evin, çevrenin, düzenin dağılmasından"],["Y","Yanlış hayatta kalıp başka fırsatları kaçırmaktan"]]],["Uzun süredir birlikte olduğun biri için başka şehre taşındın. Şimdi işler eskisi gibi değil. Aklından ne geçer?",[["G","“Onun için bu kadar şeyi bıraktım, geri adım atamam.”"],["S","“Taşınmak geçmişte kaldı, bugünkü kararı etkilemez.”"],["A","“Kaybettiğim iş geçmişte, ama bugünkü gelirim ve çevrem gerçek.”"],["Y","“Gitmeseydim bugün nerede olurdum, düşünmeden edemem.”"]]],["“Bunca yılını vermişsin, şimdi bırakılır mı?” cümlesi sana ne ifade ediyor?",[["G","Haklı bir soru, emek kolay harcanmaz"],["S","Anlamsız, geçmiş yıllar karar ölçüsü olamaz"],["A","Yarı doğru, yılların bir kısmı bugünü hâlâ etkiler"],["Y","Asıl soru verilen yıllar değil, verilecek yıllar"]]],["Bir ilişki bitse, o yıllar için ne düşünürdün?",[["G","Bunca emek bir sonuca ulaşmalıydı"],["S","Bir sayfa kapandı, geriye bakmam"],["A","Bitse de iyi yanları ve öğrendiklerim benimle kalır"],["Y","Başka bir yolu seçseydim ne olurdu, merak ederdim"]]]],"sonuclar":{"G":["Geçmişin bekçisi","Senin için verilen emek kolay silinmez ve bu sadakatin bir parçası. İktisat bunun bir kısmına batık maliyet der: Bugün ne karar verirsen ver geri gelmeyecek olan. Bedeli şu: Kararı yalnız “bunca yıl boşa gitmesin” diye vermek, bugün için kötü bir seçeneği geçmişi kurtarmak için seçmek olabilir. Bu, kalmanın yanlış olduğu anlamına gelmez. Kitabın sorusu: Devam etmek zorunda hissediyorsam, bu “yalnız geçmişte çok şey verdiğim için” mi?","25"],"S":["Temiz sayfa","Sen geçmişe takılmıyorsun: Olan olmuştur, karar bugüne göre verilir. Bu, batık maliyet yanılgısına karşı güçlü bir bağışıklık. Ama kitap öbür uca da dikkat çeker: İlişkinin bütün tarihini “batık maliyet, unut gitsin” diye silmek de en az geçmişe teslim olmak kadar yanıltıcıdır. Ortak çocuklar, konut, sosyal ağlar geçmişte kurulmuş olsa da bugünü etkiler. Risk, gerçek bağları da hesaptan düşmek.","25"],"A":["Ayırt eden","Sen geçmişi ne put yapıyor ne çöpe atıyorsun. Neyin geri gelmeyecek batık maliyet, neyin bugünü hâlâ etkileyen ilişkiye özgü sermaye olduğunu ayırmaya çalışıyorsun. Kitabın önerdiği ayrım tam olarak bu. Zorluğu şu: Kitap bu ikisini hayatta kusursuz biçimde ayırmanın kolay olmadığını da kabul eder. Ve bir şeyi hatırlatır: Sona eren yatırım ile değersiz geçmiş aynı şey değildir.","22"],"Y":["Yarına bakan","Sen kararı geçmişe değil, önündeki yıllara göre tartıyorsun. İktisadın diliyle fırsat maliyetine bakıyorsun: Bu seçimle hangi hayatlardan vazgeçiyorum? Bu, batık maliyet tuzağına karşı iyi bir pusula. Ama bir riski var: Seçilmemiş hayatlar hep daha parlak görünür, çünkü maliyetlerini yaşamamışızdır. Kitabın uyarısı: “Gerçek hayat bütün maliyetleriyle, hayali hayat ise seçilmiş sahneleriyle yarışır.”","26"]}},{"no":24,"slug":"neye-mal-oldu","ad":"Bu ilişki sana neye mal oldu?","tur":"hesap","bolum":"26","sezon":3,"acilis":"2026-12-10","kanca":"Her “evet” birkaç sessiz “hayır” taşır, seninkiler neydi?","sorular":[["Bu ilişki için işinde ya da eğitiminde bir fırsattan vazgeçtin mi?",[[0,"Hayır, hiç gerekmedi"],[1,"Küçük bir fırsattan"],[2,"Önemli bir tekliften"],[3,"İş yönümü büyük ölçüde değiştirdim"]]],["Yaşadığın şehir ve ev nasıl belirlendi?",[[0,"Zaten kendi seçeceğim yer"],[1,"Birlikte seçtik, ikimiz de biraz esnedik"],[2,"Daha çok onun ihtiyaçlarına göre"],[3,"Onun için taşındım, tek başıma olsam gitmezdim"]]],["İlişkiden önceki arkadaş çevren ve uğraşların ne durumda?",[[0,"Olduğu gibi duruyor"],[1,"Biraz seyreldi"],[2,"Büyük ölçüde ortak çevreye dönüştü"],[3,"Çoğunu geride bıraktım"]]],["Bir haftada yalnız kendine kalan saatler…",[[0,"İlişkiden önceki kadar"],[1,"Biraz azaldı"],[2,"Belirgin biçimde azaldı"],[3,"Neredeyse hiç kalmadı"]]],["Ortak kararlarda (taşınma, tatil, büyük harcama) kimin tercihi varsayılan oluyor?",[[0,"Gerçekten birlikte karar veriyoruz"],[1,"Dönem dönem değişiyor"],[2,"Çoğu zaman onunki"],[3,"Neredeyse her zaman onunki"]]],["Vazgeçtiğin şeyler ilişkide konuşuluyor mu?",[[0,"Vazgeçtiğim önemli bir şey yok"],[1,"Evet, görülüyor ve takdir ediliyor"],[2,"Pek konuşulmuyor"],[3,"Hiç görülmüyor, doğal sayılıyor"]]]],"seviyeler":[[0,"Hafif bagaj","Bu ilişki için şimdiye kadar büyük bir şeyden vazgeçmemişsin ya da vazgeçtiklerin seni pek zorlamıyor. Yine de fırsat maliyeti hiçbir zaman sıfır değildir. Kitabın deyişiyle her “evet” başka bazı ihtimallere sessizce “hayır” der. Düşük bir bedel ilişkinin değersiz olduğunu göstermez, belki yalnızca iki hayatın iyi örtüştüğünü gösterir. Bu bir ölçüm değil, bir düşünme aracıdır."],[26,"Görünür bedel","Bu ilişki sana bazı şeylere mal olmuş: biraz zaman, biraz esneklik, belki bir fırsat. Kitaba göre bir seçimin maliyetli olması onun yanlış olduğu anlamına gelmez. Tersine, neyin uğruna neyi gözden çıkardığımız neye değer verdiğimizi gösterir. Dikkat edilecek nokta, bedellerin hep aynı tarafta birikmemesi. Kitabın sorusu: “Kim hangi fırsattan vazgeçti ve bu kayıp zaman içinde nasıl telafi edildi?”"],[51,"Yüksek bedel","Bu ilişki için ciddi şeylerden vazgeçmişsin: bir şehir, bir iş, bir çevre ya da kendine ait zaman. Kitap hatırlatır: Vazgeçilen iş maaş bordrosunda görünmez, ama ilişkinin hafızasında kalabilir. Yüksek bedel yanlış seçim demek değildir. Risk, görülmeyen fedakârlığın zamanla kırgınlığa dönüşmesidir. Kitap çözümü her fedakârlığa fiyat etiketi koymakta değil, büyük kararların görünmeyen kaybedenlerini konuşabilmekte görür."],[76,"Ağır bedel","Bu ilişki hayatının yönünü büyük ölçüde belirlemiş ve vazgeçtiklerin büyük. Kitap bunun kendi başına yanlış seçim olmadığını söyler: İyi hayat, fırsat maliyeti olmayan hayat değil, vazgeçtiklerine rağmen seçtiği hayatı yaşamaya değer bulan hayattır. Ama maliyet hep aynı kişide toplanıyorsa bu bir dağılım sorunudur. Kitabın ölçütü: Ortak hayatın maliyetleri kadar kaçırılan fırsatlar da görünür olmalıdır."]],"birim":"Fırsat Maliyeti Endeksi"},{"no":25,"slug":"cok-secenek","ad":"Çok seçenek seni mutsuz mu ediyor?","tur":"profil","bolum":"27","sezon":3,"acilis":"2026-12-14","kanca":"Seçenekler çoğaldıkça sen daha mı iyi seçiyorsun, yoksa daha mı zor?","sorular":[["Bir flört uygulamasında elli yeni profil gördün. Ne yaparsın?",[["M","Hepsine bakarım, belki en iyisi sondadır"],["Y","İlk içimi ısıtan birkaçıyla konuşmaya başlarım"],["F","Önce olmazsa olmazlarıma göre elerim"],["A","Birkaçıyla yazışırım, hiçbirini kapatmam"],["B","Her birinde beğendiğim bir özelliği aklımda tutarım"]]],["Restoranda menü sayfalarca uzun.",[["M","Hepsini okurum, en iyisini bulmadan karar vermem"],["Y","İlk göze hoş gelende dururum"],["F","Yemeyeceklerimi eler, kalanlardan seçerim"],["A","Paylaşmak için birkaç tane söyleriz, sonra bakarız"],["B","Sipariş verdikten sonra yan masanınkine bakarım"]]],["İyi giden bir ilişkin var. Aklından en çok ne geçer?",[["M","“Acaba daha iyisi var mı?”"],["Y","“İyi ki bu kadar kolay oldu.”"],["F","“Benim için önemli olan her şey yerinde.”"],["A","“Şimdilik iyi, bakalım ne olacak.”"],["B","“Keşke onda şu özellik de olsaydı.”"]]],["Önemli bir karar verdikten sonra (ev, iş, partner)…",[["M","Diğer seçenekleri düşünmeye devam ederim"],["Y","Konu kapanır, önüme bakarım"],["F","Ölçütlerime uyuyorsa içim rahattır"],["A","Geri dönebileceğimi bilmek beni rahatlatır"],["B","Başkalarının seçimleriyle kıyaslarım"]]],["Bir arkadaşın sana birini tanıştırmak istiyor.",[["M","Önce başka kimler var, onları da duymak isterim"],["Y","Olur, iyi biriyse neden olmasın"],["F","Önce birkaç temel şey sorarım: yaşı, şehri, hayattan beklentisi"],["A","Tanışırım ama kimseye söz vermem"],["B","Dinlerken onu önceki sevgililerimle kıyaslarım"]]],["Hangi cümle sana daha yakın?",[["M","En iyisi varken ikincisine razı olmam."],["Y","Yeterince iyi, çoğu zaman en iyisidir."],["F","Ne istediğini bilen az yorulur."],["A","Kapılar açık kaldıkça özgürüm."],["B","Her insanda başka bir şey eksik."]]]],"sonuclar":{"M":["En iyinin peşinde","Sen yeterince iyiyle yetinmiyor, ulaşılabilecek en iyiyi arıyorsun. Kitap buna maksimize etme eğilimi der. Schwartz ve arkadaşlarının çalışmalarında bu eğilim daha fazla pişmanlık ve daha düşük seçim doyumuyla ilişkiliydi, ama kitap bu bulguların tartışıldığını da not eder. Romantik seçimde iş daha zordur, çünkü “en iyi partner”in tek boyutlu bir sıralaması yoktur. Risk şu: Her yeni seçenek aramanın bitişini biraz daha erteleyebilir.","27"],"Y":["Yeterince iyi","Sen “benim için uygun” olanı bulduğunda aramayı bırakabiliyorsun. Her yeni adayı yeniden yarışmaya sokmadığın için seçenek bolluğu seni pek yormaz. Kitabın anlattığı karar yükünden en az etkilenen tarz bu olabilir. Yine de kitap bir uyarı yapar: Kolay karar ile iyi hayat aynı şey değildir. Kitaba göre bir insanın bazı özellikleri ancak zaman içinde öğrenilebilir.","27"],"F":["Filtreci","Sen ne istediğini biliyorsun ve uymayanları erkenden eliyorsun. Kitaba göre tercihlerin netliği arama maliyetini azaltır, bu yüzden geniş bir seçenek kümesi sana fayda bile sağlayabilir. Riski şu: Filtre sayısı arttıkça henüz tanımadığın insanlarla beklenmedik uyum ihtimali de erkenden yok olabilir. Boy, yaş, meslek gibi kolay filtrelenen özellikler, mizah ya da duyarlılık gibi zamanla görülenlerin önüne geçebilir.","27"],"A":["Açık kapı","Sen seçeneklerini açık tutmayı seviyorsun. Bu esnekliğin bir değeri var, iktisatta buna opsiyon değeri denir. Ama kitabın uyarısı şu: Romantik hayatta bütün opsiyonları korumanın bedeli, partnerin de sana aynı ölçüde yatırım yapmaması olabilir, çünkü o da ilişkinin her an başka seçeneğe değiştirilebileceğini düşünür. Kitabın sözüyle: “Özgürlük, kapıyı kapatmanın kendi kararımız olmasıdır.”","26"],"B":["Hayali rakip","Sen seçtikten sonra da karşılaştırmayı bırakmıyorsun: birinin mizahı, ötekinin romantikliği, bir başkasının başarısı. Karşılaştırma bazen işe yarar, başka çiftlerde görülen iyi bir davranış kendi ilişkini geliştirebilir. Ama kitap bir tuzağa dikkat çeker: Herkesin en güçlü yanından kafanda bir bileşik partner kurarsan gerçek insanın kazanması mümkün değildir. Bolluk böylece en güçlü rakibi yaratır: hiç var olmamış kusursuz alternatif.","27"]}},{"no":26,"slug":"guven-sermayesi","ad":"Güven Sermayen artıda mı, ekside mi?","tur":"hesap","bolum":"24","sezon":3,"acilis":"2026-12-17","kanca":"Güven iyi çalıştığında görünmez, peki seninki ne kadar birikmiş?","sorular":[["Partnerin küçük sözlerini (“ararım”, “gelirim”, “hallederim”) ne sıklıkla tutar?",[[3,"Neredeyse her zaman"],[2,"Çoğu zaman"],[1,"Yarı yarıya"],[0,"Nadiren"]]],["Ona anlattığın bir sır ya da zayıf bir anın ne oldu?",[[3,"Korudu, hiç gündeme getirmedi"],[2,"Korudu ama bir kez ima ettiği oldu"],[1,"Bir tartışmada kullandığı oldu"],[0,"Başkalarıyla paylaştığını öğrendim"]]],["Bir sorun çıktığında partnerin genellikle…",[[3,"Ortada olur, sorumluluğunu alır"],[2,"Biraz gecikse de gelir"],[1,"Ortadan kaybolur, sonra döner"],[0,"Hatayı başkasının üzerine atar"]]],["Bir hata yaptığında partnerin…",[[3,"Kendiliğinden söyler"],[2,"Sorulunca dürüstçe anlatır"],[1,"Önce küçültür, sonra kabul eder"],[0,"Kanıt çıkana kadar inkâr eder"]]],["Bir gecikme ya da belirsiz bir mesaj karşısında sen ne yaparsın?",[[3,"Pek düşünmem, bir açıklaması vardır"],[2,"Merak eder, sorarım, geçer"],[1,"Kafama takılır, kontrol etme isteği duyarım"],[0,"Doğrulamadan rahat edemem"]]],["Önemli konularda (para, sağlık, ortak gelecek) birbirinize bilgi veriyor musunuz?",[[3,"Açıkça veririz"],[2,"Çoğunlukla, bazı şeyler zamanla söylenir"],[1,"Bazı önemli şeyleri sonradan öğrendiğim oldu"],[0,"Kararlarımı eksik bilgiyle verdiğimi hissediyorum"]]]],"seviyeler":[[0,"Ekside","Cevapların güven hesabının şu an ekside olduğunu düşündürüyor: Doğrulama ihtiyacı yüksek, verilen sözler az bilgi taşıyor. Kitap bunu kişisel bir kusur saymaz: Hak edilmiş kuşku da sağlıklı bilgi işleme olabilir. Düşük güvenin bedeli sürekli kontrol, doğrulama ve savunmadır. Kitaba göre güveni bozan davranışsa, onaran da davranış olmalıdır. Güvenliğin tehdit altında olduğu yerde ise kitap önceliği kişinin korunmasına verir."],[26,"Kırılgan bakiye","Güven hesabın açık ama kırılgan: Bazı sözler tutuluyor, bazı konularda şüphe kalıyor. Kitap güveni tek bir puan değil, alanlara göre değişen beklentiler bütünü olarak görür. Sadakatine güvendiğin birinin dakikliğine güvenmemen mümkündür. Risk, küçük tekrarların örüntüye dönüşmesidir. O zaman soru “Bu kez ne oldu?”dan “Bu kişinin sözü geleceğe ilişkin ne kadar bilgi taşıyor?” sorusuna kayar."],[51,"Artıda","Güven hesabın artıda: Sözler çoğunlukla tutuluyor, sorun çıktığında kimse ortadan kaybolmuyor. Kitap bunun değerini işlem maliyetiyle anlatır: Birbirine güvenen çift her bilgiyi doğrulamak ya da her gecikmeyi soruşturmak zorunda kalmaz. Yine de bu sermaye bankadaki para gibi mekanik işlemez. Küçük bir gecikme yılların güvenini yok etmeyebilir, ama tek bir büyük ihanet geçmişin bütün yorumunu değiştirebilir."],[76,"Güçlü sermaye","Güven sermayen güçlü: Davranışlar sözleri destekliyor, kırılganlığın korunuyor. Kitap güvenin en büyük getirisini huzurdan çok hareket alanı olarak görür. Sürekli savunmada kalmadan işine, arkadaşlarına ve kendine zaman ayırabilirsin. Tek uyarı: Kitabın hedefi maksimum güven değil, davranışla uyumlu güven düzeyidir. Kitabın deyişiyle iyi güven, kanıta rağmen değil kanıt sayesinde güçlenir. Bu endeks de bir düşünme aracıdır."]],"birim":"Güven Sermayesi Endeksi"},{"no":27,"slug":"aldatma-mitleri","ad":"Aldatma hakkında 6 yaygın inanç: Kaçı doğru?","tur":"mit","bolum":"23","sezon":3,"acilis":"2026-12-21","kanca":"Herkesin aldatma hakkında kesin bir fikri var ama veriler o kadar kesin konuşmuyor.","sorular":[["Bir kez aldatan, sonraki ilişkisinde de mutlaka aldatır.",false,"Yanlış. Knopp ve arkadaşlarının 484 yetişkini iki ardışık ilişki boyunca izlediği çalışmada, ilk ilişkisinde sadakatsizlik bildirenlerin sonraki ilişkide de bildirme olasılığı yaklaşık üç kat yüksekti. Ama kitap bunun bir risk farkı olduğunu, kader olmadığını vurgular: Üç kat yüksek olasılık yüzde yüz kesinlik demek değildir."],["Mutlu bir ilişkide aldatma olmaz, aldatıldıysa ilişki zaten kötüydü.",false,"Yanlış. Düşük ilişki doyumu bazı çalışmalarda sadakatsizlikle birlikte görülür, ama nedensellik ters de işleyebilir: Sadakatsizliğin kendisi doyumu düşürebilir. Kitaba göre memnun olmadığı halde hiç aldatmayan çok sayıda insan vardır ve mutlu olduğunu bildirenlerin bir bölümü de ilişki dışı davranış yaşayabilir."],["İnsanlar neyin aldatma sayılacağı konusunda her zaman aynı çizgiyi çekmez.",true,"Doğru. Wilson ve arkadaşlarının ölçeğinde davranışlar “açık”, “aldatıcı” ve “belirsiz” olarak gruplanmış, belirsiz davranışlarda görüşler daha fazla ayrışmıştır. Kitabın özeti: İnsanlar aldatma kavramının merkezinde büyük ölçüde uzlaşabilir, fakat sınırlarında ciddi farklılık gösterebilir."],["Partnerden kasıtlı olarak gizlenen bir borç ya da harcama da bir tür sadakatsizlik sayılabilir.",true,"Doğru. Garbinsky ve arkadaşları buna finansal sadakatsizlik der: Partnerin onaylamayacağı beklenen bir finansal davranışı yapıp kasıtlı olarak ondan saklamak. Kitaba göre her kişisel harcamayı açıklamamak bu kapsama girmez, anahtar unsur beklenen ortak kural ile kasıtlı gizlilik arasındaki farktır."],["Aldatma ortaya çıktıktan sonra ilişki artık onarılamaz.",false,"Yanlış. Kitabın aktardığı terapi araştırmalarında, sadakatsizlik yaşayan çiftlerin başlangıçtaki yüksek sıkıntısı ile diğer çiftler arasındaki fark tedavi sonunda ve altı aylık izlemde büyük ölçüde kapanabilmiştir. Kitap bunun “aldatmadan sonra mutlaka birlikte kalınmalıdır” anlamına gelmediğini de ekler: Gösterilen yalnızca, sadakatsizliğin ilişkiyi otomatik olarak onarılamaz hale getirmediğidir."],["Aldatmanın arkasında tek bir neden değil, birbirinden farklı motivasyonlar olabilir.",true,"Doğru. Selterman ve arkadaşlarının sadakatsizlik deneyimi yaşamış 495 kişiyle yaptığı çalışmada öfke, ihmal edilme, sevginin azalması, düşük bağlılık, özsaygıyı güçlendirme arzusu ve stres gibi durumsal etkenler ayrı motivasyonlar olarak ortaya çıktı. Örneklemin önemli bölümü genç yetişkinlerdi, yani dağılım genellenemez. Kitap bunun sorumluluğu ortadan kaldırmadığını da vurgular: Açıklama, mazeret değildir."]],"seviyeler":[[0,"Atasözlerine güvenen","İnançlarının çoğu gündelik dilin kesin cümlelerine yakın: “Bir kez aldatan hep aldatır”, “Mutlu olan aldatmaz.” Kitap bu cümlelerin bazılarında bir gerçek payı olduğunu ama verilerin bu kesinliği taşımadığını gösterir. Araştırmalar çoğu zaman risk farkından söz eder, kaderden değil. Geçmiş davranış bir risk bilgisi taşıyabilir, ama insanın üzerine ömür boyu sabit bir etiket yapıştırmaz. Kitabın uyarısı: “Risk değerlendirmesi ile insanı mahkûm etmek aynı şey değildir.”"],[3,"Gri alanı gören","Bazı inançlarında verilerle aynı yerdesin, bazılarında atasözlerine yakınsın. Aldatma konusu tam da bu yüzden zor: İnsanlar merkezde büyük ölçüde uzlaşır, sınırlarda ise ciddi biçimde ayrışır. Kitaba göre iki insan “tek eşliyiz” dediğinde mutlaka aynı sözleşmeye imza atmış olmayabilir. Sadakat yalnız yasakların listesi değil, sınırlar konusunda ortak beklentidir. Dijital iletişim de bu gri alanı büyütür."],[5,"İhanet ekonomisti","Aldatma hakkındaki yaygın inançları verilerden ayırt edebiliyorsun. Kitabın vardığı yer de bu: Aldatmanın ekonomik çekirdeği partner sayısından çok, üzerinde anlaşılmış kuraldan gizli sapmadır. Bu yüzden asıl maliyet yalnız kaybedilen ilişki değil, diğer insanın eksik bilgiyle verdiği kararlardır. Gizlilik bu yüzden davranışın üstüne ayrı bir maliyet ekler. Şimdi bölümün kapanış sorusu: “Bir kez bozulan güven yeniden kurulabilir mi ve kurulacaksa bunun bedelini hangi davranışlar, hangi zaman ve hangi karşılıklılık öder?”"]]},{"no":28,"slug":"affetmek-guvenmek","ad":"Affetmek, güvenmek, uzlaşmak: Hangisinde takılıyorsun?","tur":"profil","bolum":"24","sezon":3,"acilis":"2026-12-24","kanca":"Üç ayrı karar çoğu zaman tek karar sanılır, sen hangisinde duruyorsun?","sorular":[["Yakın biri sana önemli bir konuda yalan söyledi ve özür diledi. İlk haftalarda sen?",[["F","Öfkem geçmiyor, özrü duymak bile zor geliyor"],["G","Özrü kabul ederim ama her sözünü tartarım"],["U","Kızgın değilim, ama nasıl devam edeceğimizi bilemem"],["H","Özür dilediyse konu kapanır, uzatmam"]]],["Sana göre affetmek…",[["F","Yapılanı kabul edilebilir saymak gibi gelir"],["G","Olabilir, ama güven ayrı bir hesaptır"],["U","İnsanı affetmek, ilişkiye devam etmek demek değildir"],["H","Unutup yola devam etmektir"]]],["Güveni sarsmış biri “Artık bana güvenmelisin” derse…",[["F","Bunu isteme hakkı olmadığını düşünürüm"],["G","Söz yetmez, davranışını görmem gerekir derim"],["U","Güvensem bile nasıl devam edeceğimizi konuşmamız gerekir"],["H","Haklı olabilir, ne kadar uzatabiliriz ki"]]],["Bir arkadaşın, partnerinin ondan gizlediği bir borcu öğrenmiş. Ona ne dersin?",[["F","“Kızgınlığın çok doğal, acele etme.”"],["G","“Bundan sonra hesapları birlikte görmek isteyebilirsin.”"],["U","“Affetmek ile birlikte kalmak ayrı kararlar.”"],["H","“Para bu, çözülür, büyütme.”"]]],["Böyle bir süreçte seni en çok ne zorlar?",[["F","Yaşananı içimde taşımaya devam etmek"],["G","Telefonu çaldığında aklıma kötü ihtimallerin gelmesi"],["U","Her şey yoluna girmiş gibi davranmak"],["H","Konunun tekrar tekrar açılması"]]],["Hangi cümle sana daha yakın?",[["F","Affetmek hak edilir."],["G","Affettim ama eskisi gibi değil."],["U","Affetmek bir şey, kalmak başka."],["H","Kin tutan önce kendini yorar."]]]],"sonuclar":{"F":["Affetmede takılan","Senin için yaşanan şey kolay kapanmaz. Kitap affetmeyi unutmak ya da yapılanı kabul edilebilir saymak olarak görmez, daha çok sürekli misilleme ve öfke döngüsünden çıkabilmekle ilişkilendirir. Bazı çalışmalarda affetme eğilimi daha az olumsuz çatışmayla bağlantılı bulunmuştur. Ama kitap bunun “ne yapılırsa yapılsın affedin” anlamına gelmediğini vurgular. Onarımın takvimini de ihlali yapan kişi tek taraflı belirleyemez.","23"],"G":["Yeniden güvenmede takılan","Sen affedebiliyorsun ama güvenin geri gelmesi zaman alıyor. Kitap bu ikisini zaten ayrı kararlar sayar. İhlalden sonra daha fazla bilgi istemek anlaşılırdır, ama geçici güvence ile kalıcı gözetim aynı şey değildir. Kitabın benzetmesiyle eğitim tekerlekleri bisiklet sürmeyi öğretir, beceri ancak onlarsız dengede durulduğunda yerleşir. Belki hedef eski güven değil, yeni bilgiyle kurulan yeni güvendir.","24"],"U":["Uzlaşmada takılan","Sen insanı affedebiliyor, hatta ona yeniden güvenebiliyorsun. Takıldığın yer, ilişkinin hangi koşullarla devam edeceği. Kitap bunu çok net ayırır: Affetmek, güvenmek ve uzlaşmak üç ayrı karardır. Birlikte kalmak da tek başına gerçek affetmenin kanıtı değildir. Ekonomik dille söylersek bağışlama, geçmiş borcun kayıtlardan sihirli biçimde silinmesi değil, ilişkinin hangi koşullarla süreceğine dair yeni bir karardır.","23"],"H":["Hızlı kapatan","Sen kırgınlığı uzatmayı sevmiyorsun, özür geldiyse sayfayı çeviriyorsun. Bu ilişkiye esneklik kazandırabilir. Ama kitap bir sınır hatırlatır: McNulty’nin yeni evli çiftlerle çalışmasında sorunlu davranış sık tekrarlanıyorsa yüksek affedicilik her koşulda olumlu sonuç vermemiştir. Kitabın deyişiyle affetmenin iyi olması, sınırların gereksiz olduğu anlamına gelmez. Özür bir sinyaldir, güvenilirliğini sonraki davranış belirler.","24"]}},{"no":29,"slug":"kriz-senaryolari","ad":"Ne yapardın? 8 kriz senaryosu","tur":"senaryo","bolum":"22","sezon":3,"acilis":"2026-12-28","kanca":"Kriz geldiğinde herkesin gözü başka bir yere kayar, seninki nereye gidiyor?","sorular":[["Yıllardır birliktesiniz ve son zamanlarda hep aynı kavga dönüyor. Bir akşam yalnız kaldığında ilk ne düşünürsün?",[["H","Bu ilişkiye ne kadar emek verdiğimi"],["G","Onun neden değiştiğini, bir şey mi sakladığını"],["A","Başka bir hayatın nasıl olabileceğini"],["B","Birbirimizden ne beklediğimizi hiç konuşup konuşmadığımızı"],["C","Kendi ayaklarım üstünde nasıl bir hayat sürdüğümü"]]],["Partnerinin eski sevgilisiyle senden habersiz uzun uzun mesajlaştığını öğrendin.",[["H","“Bunca yılımızın üstüne bu mu?” diye düşünürüm"],["G","Önce bütün yazışmaları görmek isterim"],["A","Demek ki o da başka seçeneklere bakıyor, derim"],["B","Bunun bizim için aldatma sayılıp sayılmadığını konuşmak isterim"],["C","İlişkinin dışında kendime ait neyim var, ona bakarım"]]],["Partnerin ortak bütçeden habersiz büyük bir harcama yaptığını itiraf etti ve özür diledi.",[["H","Harcanan parayı ve şimdiye kadar verdiklerimi tartarım"],["G","Bundan sonra bütün harcamaları görmek isterim"],["A","Başka biri olsa böyle yapmazdı, diye düşünürüm"],["B","Para konusunda hangi kuralla yaşadığımızı yeniden konuşuruz"],["C","Kendi birikimimin ve gelirimin ne durumda olduğuna bakarım"]]],["Uzun zamandır ilişkiye emek veren hep senmişsin gibi hissediyorsun.",[["H","Kimin ne verdiğine dair aklımda bir liste oluşur"],["G","Onun gerçekte ne kadar istekli olduğunu anlamaya çalışırım"],["A","Başka biriyle bu kadar uğraşır mıydım, diye düşünürüm"],["B","Neyi beklediğimi açıkça söylemediğimi fark ederim"],["C","Kendi arkadaşlarımı ve uğraşlarımı ihmal ettiğimi fark ederim"]]],["Partnerine başka şehirde iyi bir iş teklifi geldi. Sen burada işinin en iyi yerindesin.",[["H","Şimdiye kadar kimin işi için kim fedakârlık etti, ona bakarız"],["G","Bu konuyu ne zamandır düşündüğünü merak ederim"],["A","Gitmek de kalmak da bir şeyden vazgeçmek, ikisini tartarım"],["B","İkimizin de bu ilişkiden ne beklediğini masaya koyarız"],["C","Hangi karar çıkarsa çıksın kendi işimi korumanın yolunu ararım"]]],["Zor bir dönemdesiniz. Bir arkadaşın flört uygulamasını gösterip “bak ne çok seçenek var” diyor.",[["H","Bunca yatırımı bırakıp sıfırdan başlamak bana pahalı gelir"],["G","Ekrandakilerin gerçekte nasıl biri olduğunu kim bilebilir, derim"],["A","Merakla bakarım, belki gerçekten daha iyisi vardır"],["B","Önce ben aslında ne istiyorum, onu bilmem gerek, derim"],["C","Seçenek olduğunu bilmek içimi rahatlatır ama acele etmem"]]],["Partnerin “Beni artık anlamıyorsun” dedi.",[["H","Ben de onun için yaptıklarımı sıralarım"],["G","Bunu neden şimdi söylediğini, arkasında ne olduğunu düşünürüm"],["A","Belki başka biriyle daha uyumlu olurdu, diye geçer aklımdan"],["B","Ondan ne beklediğimi, onun benden ne beklediğini sorarım"],["C","Hayatımın yalnız bu ilişkiden ibaret olmadığını hatırlarım"]]],["Bir krizi atlattınız ve çevreniz “artık eskisi gibisiniz” diyor. Sen?",[["H","Bu kriz bize neye mal oldu, hâlâ hesaplıyorum"],["G","Bir süre daha gözüm açık olacak"],["A","Başka yolu seçseydik ne olurdu, arada bir düşünürüm"],["B","Eskisi gibi değiliz, artık yeni kurallarımız var"],["C","Bu süreçte kendime ait alanı korumanın iyi geldiğini gördüm"]]]],"sonuclar":{"H":["Hesap defteri","Krizde ilk refleksin, verilenleri ve alınanları tartmak. Bu soğukluk değil: Kitap “gerçek aşk hesap yapmaz” cümlesinin bazen eşitsizliği görünmez kıldığını söyler. Ama defterin bir tuzağı var. Geçmişte verilenlerin bir kısmı geri alınamayacak batık maliyettir ve bugünkü karara gereğinden fazla ağırlık verebilir. Her davranışın anında eşdeğer karşılığını beklemek de ilişkiyi muhasebe defterine çevirebilir.","25"],"G":["Gözcü","Kriz anında önce bilgiye ihtiyaç duyuyorsun: Ne oldu, neden oldu, başka ne var? Kitap ihlalden sonra daha fazla şeffaflık istemenin anlaşılır olduğunu söyler, ama geçici güvence ile kalıcı gözetimi ayırır. Denetimin bilgi talebinin doğal bir sonu yoktur: Telefon temiz çıkınca bu kez silinmiş mesajlar akla gelebilir. Kitabın sözüyle: Güvenin alternatifi kusursuz bilgi değildir.","24"],"A":["Alternatif tartan","Kriz anında aklın seçilmemiş yollara gidiyor: başka biri, başka bir şehir, başka bir hayat. Bu, fırsat maliyetini görmenin doğal bir yolu ve kitaba göre bu farkındalık bazen gerçekten işe yarar. Ama kitap bu karşılaştırmanın adil olmadığını hatırlatır: Mevcut partnerin hatalarını biliyoruz, vazgeçtiğimiz kişinin yapacağı hataları bilmiyoruz. Kitabın sözüyle: Alternatif hayat maliyetsiz değildir, yalnız maliyetlerini henüz yaşamamışızdır.","26"],"B":["Beklenti yazarı","Kriz anında sen sorunun kişide mi, beklentide mi olduğunu soruyorsun. Kitaba göre beklenti açığı her zaman partnerin hatası değildir: Beklenti çelişkili, kaynaklarla uyumsuz ya da hiç konuşulmamış olabilir. Bu güçlü bir tarz. Riski şu: Her krizi beklenti meselesi saymak, gerçekten vazgeçilmez olanı gözden kaçırabilir. Kitabın hatırlattığı gibi beklentileri yeniden düzenlemek, temel sınırları silmek değildir.","28"],"C":["Kendi ayağında","Kriz anında sen kendi hayatının ayakta olduğundan emin olmak istiyorsun: işin, gelirin, arkadaşların. Kitap bunu kaçış hazırlığı saymaz: Gitme imkânının artması, gitme arzusunun artmasıyla aynı şey değildir. Kitaba göre gidebilme kapasitesi kalmanın anlamını bile güçlendirebilir. Riski şu: Bu dayanaklar ortak yatırımın yerini alırsa ilişki “seçilmiş seçenek” olmaktan çok “şimdilik tutulan seçenek” gibi hissedebilir.","22"]}},{"no":30,"slug":"kriz-aninda","ad":"Kriz anında aynı tarafta mısınız?","tur":"cift","bolum":"24","sezon":3,"acilis":"2026-12-31","kanca":"Ayrı ayrı çözün, sonra karşılaştırın: Kriz geldiğinde aynı yöne mi koşuyorsunuz?","sorular":[["Büyük bir tartışmadan sonra:",["Aynı gün konuşmak","Bir gece bekleyip konuşmak"]],["Güveni sarsan bir olaydan sonra öncelik:",["Neden olduğunu anlamak","Bundan sonrasını konuşmak"]],["Bir özür en çok neyle inandırıcı olur:",["Hemen ve açıkça dile getirilmesiyle","Zamanla davranışa yansımasıyla"]],["Krizden sonra telefon ve şifreler:",["Bir süre açık tutulur","Herkesin alanı korunur"]],["Para yüzünden bir kriz çıkarsa:",["Kurallar açıkça yazılır","Güvene dayalı esneklik korunur"]],["Zor bir konu konuşulurken:",["Her şey bir kerede masaya konur","Adım adım, parça parça konuşulur"]],["Affetmek:",["Sayfayı tamamen kapatmaktır","Kaydı tutup yola devam etmektir"]],["Kriz atlatılınca ilişki:",["Eski haline dönmeli","Yeni kurallarla yeniden kurulmalı"]],["Kalmak ya da gitmek tartışılırken ağır basan:",["Birlikte geçirilen yıllar","Önümüzdeki yıllar"]],["Zor dönemde destek:",["İki kişinin arasında kalır","Arkadaş, aile ya da uzmanla da paylaşılır"]]],"seviyeler":[[0,"Farklı kriz dilleri","Kriz anında çoğu konuda farklı yerlerde duruyorsunuz. Bu ilişkinin zayıf olduğunu göstermez, krizi farklı dillerle yaşadığınızı gösterir. Kitap ilişkiyi bir eksik sözleşme olarak görür: Ortaya çıkacak her durumu önceden yazamazsınız, her şeyin yazılı kurala bağlanması da mümkün değildir. Yazılmayan yerleri birbirinizin iyi niyeti, adalet anlayışı ve geçmiş davranışları doldurur. Farklı cevap verdiğiniz maddeler, henüz konuşulmamış maddeler olabilir."],[4,"Kısmi uzlaşma","Bazı konularda aynı taraftasınız, bazılarında değil. Kitaba göre güven tek bir puan değil, alanlara göre değişen beklentiler bütünüdür. Para konusunda aynı yerde durup konuşma biçiminde ayrışmanız mümkündür. Ayrıştığınız maddelere birlikte bakın. Kitabın sözüyle sağlam ilişki açık anlaşmalar ile hak edilmiş güveni birlikte kullanır. Güven sözleşmenin alternatifi değildir, ikisinden biri tek başına yetmez."],[7,"Aynı tarafta","Kriz anında çoğu konuda aynı yerde duruyorsunuz. Bu, kitabın güven sermayesi dediği şeyin değerli yanı: Her küçük kararı yeniden müzakere etmek zorunda kalmadığınızda ilişkinin işlem maliyeti düşer. Yine de kitap bir uyarı yapar: Krizin kendisi ilişkiyi otomatik olarak güçlendirmez. Kâğıt üzerindeki uyum bir başlangıçtır, güven ise kitaba göre davranıştan beslenir."],[9,"Ortak kriz haritası","Neredeyse her maddede aynı cevabı verdiniz. Kriz geldiğinde ne yapacağınız konusunda ortak bir haritanız var gibi. Kitabın deyişiyle güven belirsizliği ortadan kaldırmaz, belirsizlik içinde birlikte hareket etmenin maliyetini düşürür. Sizin cevaplarınız bu maliyetin düşük olabileceğini, eksik sözleşmenin boşluklarını benzer biçimde doldurduğunuzu düşündürüyor. Gerçek sınav yine davranışta: Kitaba göre özür bir sinyaldir. Güvenilirliğini sonraki davranış belirler."]]},{"no":31,"slug":"tinder-oncesi-sonrasi","ad":"Tinder öncesi mi aşıksın, sonrası mı?","tur":"nesil","bolum":"30","sezon":4,"acilis":"2027-01-04","kanca":"Aşkı mahalle mi tanıştırırdı, arkadaş mı, ekran mı? Senin refleksin hangi çağdan?","sorular":[["Hayatının aşkıyla nasıl tanışmak isterdin?",[["M","Aynı sokakta, aynı okulda ya da bir düğünde"],["A","Bir arkadaşın “Sizi tanıştırmalıyım” demesiyle"],["I","Uzun yazışmalarla başlayan bir tanışıklıkla"],["K","Birkaç kilometre ötede, ekranda karşıma çıkarak"],["Y","Beni iyi tanıyan bir uygulamanın önerisiyle"]]],["Yeni biriyle tanıştın. Güvenmeden önce neye bakarsın?",[["M","Ailesini ve çevresini kimlerin tanıdığına"],["A","Ortak arkadaşımızın onun hakkında ne dediğine"],["I","Yazdıklarının zamanla birbirini tutup tutmadığına"],["K","Profilinin doğrulanmış olup olmadığına"],["Y","Uygulamanın uyum yorumuna ve önerisine"]]],["Aday havuzun ne kadar geniş olmalı?",[["M","Tanıdığım çevre yeter, uzağı bilmem"],["A","Arkadaşlarımın arkadaşları kadar"],["I","Şehrimin, hatta ülkemin sınırını aşabilmeli"],["K","Ne kadar çok profil, o kadar iyi"],["Y","Geniş olsun ama birkaç iyi adaya indirilsin"]]],["Seni en çok ne yorar?",[["M","Herkesin her şeyi bilmesi"],["A","Ayrılınca arkadaşların arada kalması"],["I","Yüz yüze görüşmenin hep ertelenmesi"],["K","Sonu gelmeyen profil kaydırmak"],["Y","Mesajın ne kadarının bana ait olduğunu düşünmek"]]],["İlk adım nasıl atılır?",[["M","Mesaja gerek yok, yüz yüze selam verilir"],["A","Arkadaşım aracılığıyla haber gönderirim"],["I","Uzun, özenli, birkaç paragraflık bir mesajla"],["K","Kısa bir espri yazar, hemen gönderirim"],["Y","Taslağı önce bir yapay zekâya düzelttiririm"]]],["Hangi cümle sana yakın?",[["M","Kısmet, yakınında olandır."],["A","Güvendiğin birinin önerisi altın değerindedir."],["I","Mesafe, iyi bir yazışmayla kısalır."],["K","Seçenek çoksa doğruyu bulma şansı da çoktur."],["Y","Doğru veri, doğru kişiyi getirir."]]]],"sonuclar":{"M":["Mahalle çağı","Senin aşk haritan yakın çevreyle çizili: Aynı sokak, aynı okul, bir düğün masası. Kitaba göre tarih boyunca bir insanın karşılaşabileceği partner sayısını büyük ölçüde coğrafya belirledi. Bu dünyada aile ve mahalle hem karşılaşma alanı hem dolaylı bir güven kontrolüydü. Bedeli şu: Varlığından haberdar olmadığın biriyle ne kadar uyumlu olabileceğinin pratikte hiçbir önemi yoktu. Havuz dar, güven sağlam.","30"],"A":["Arkadaş köprüsü çağı","Sen tanışmanın en güvenilir yolunu bir arkadaşın kefaletinde görüyorsun. Kitap bunu şöyle anlatır: “Onu yıllardır tanıyorum” cümlesi kusursuz garanti değildi, ama iki yabancı arasındaki bilgi problemini azaltabilirdi. İktisatta bu bir aracılık hizmetidir. ABD verilerine göre çevrim içi tanışma yaklaşık 2013 civarında bu yolu geride bıraktı. Senin bedelin, havuzun arkadaş çevren kadar kalması.","30"],"I":["İnternet çağı","Sen coğrafyayı aşmaya hazırsın ama aceleci değilsin. Kitaba göre tren, otomobil, üniversite ve büyük şehirler partner havuzunu genişletti. Ama aşk piyasasının sınırları uzun süre büyük ölçüde fiziksel dünyanın sınırlarıydı. Senin çağında yabancılar birbirine bağlanıyor ama henüz telefonda sıraya dizilmiyordu. Güçlü yanın, yazışmaların zamanla biriktirdiği bilgi. Bedeli: Profil ne kadar ayrıntılı olursa olsun ses tonunu, hareketleri ve iki insan arasındaki kimyayı taşıyamaz.","30"],"K":["Kaydırma çağı","Sen Tinder sonrasının insanısın: Geniş havuz, hızlı karar, sağa ya da sola. Kitaba göre değişen yalnız parmak hareketi değil. Eskiden aile, arkadaş ve mahallenin yaptığı eşleştirmenin bir bölümünü artık platformlar yapıyor. Avantajın, başka türlü hiç karşılaşmayacağın insanlara ulaşmak. Bedeli: Milyonlarca profil milyonlarca gerçek seçenek demek değil, çünkü karşı tarafın da seni seçmesi gerekir. Kıt olan artık dikkat.","30"],"Y":["Yapay zekâ çağı","Sen bir adım öndesin: Partner aramanın emeğini yazılıma devretmeye hazırsın. Kitap bunun çoktan başladığını yazar: Tinder Mart 2026’da “Chemistry” adlı yapay zekâ destekli kişiselleştirme katmanını duyurdu. Kazanç açık, arama maliyeti düşer. Bedeli daha sinsi: Geçmiş tercihlerinden öğrenen bir sistem sana hep benzerini getirebilir ve tesadüfen iyi biriyle karşılaşma ihtimalini azaltabilir.","34"]}},{"no":32,"slug":"hangi-on-yil","ad":"Aşk hayatın hangi on yıla ait?","tur":"nesil","bolum":"29","sezon":4,"acilis":"2027-01-07","kanca":"Bazı insanlar takvimle değil, aşk anlayışıyla yaşar. Seninki hangi yılda kaldı?","sorular":[["Evlilik teklifi denince aklına ne gelir?",[["P","Ömür boyu sürecek bir taş, bir yüzük"],["U","İki hayatın birlikte bir düzen kurması"],["D","Genç yaşta, heyecanla verilen bir söz"],["O","Önce mesaj, sonra buluşma, sonra karar"],["Z","Her şey oturduktan sonra konan son taş"]]],["Evlenmek için doğru zaman ne zaman?",[["P","Sonsuza kadar süreceğine emin olunca"],["U","Kimin neyi üstleneceği belli olunca"],["D","Yirmili yaşlarda, hayatı birlikte kurmak için"],["O","Birbirimizi yeterince tanıyınca, yaş fark etmez"],["Z","İş, ev ve birikim tamamlanınca"]]],["İlişkide en çok neyi değerli bulursun?",[["P","Kalıcılığı, sonsuza kadar sürmesini"],["U","İş bölümünü, herkesin işini bilmesini"],["D","Birlikte sıfırdan başlamayı"],["O","Geniş bir havuzdan seçmiş olmayı"],["Z","Birlikte kendimizi geliştirmeyi"]]],["Partnerinle nasıl tanışmış olmayı isterdin?",[["P","Benden çok farklı bir çevreden gelen biriyle"],["U","Hayat düzenime uyacak biriyle, tanıdık aracılığıyla"],["D","Ortak bir arkadaşın tanıştırmasıyla"],["O","Bir uygulamada, hiç ortak tanıdık olmadan"],["Z","Yapay zekânın önerdiği birkaç aday arasından"]]],["Para konusunda ilişkide…",[["P","Büyük jest, büyük bağlılık demektir"],["U","Biri kazanır, biri evi çevirir, ikisi de emektir"],["D","Az parayla başlanır, birlikte büyütülür"],["O","Herkes kendi hesabını bilir, ortak gider konuşulur"],["Z","Önce ekonomik eşik aşılır, sonra nikâh kıyılır"]]],["Hangi cümle sana yakın?",[["P","Bazı şeyler sonsuza kadardır."],["U","İyi evlilik, iyi bir iş bölümüdür."],["D","Önce evlenilir, sonra kurulur."],["O","Aşkı artık arkadaş değil, ekran tanıştırıyor."],["Z","Önce kurulur, sonra evlenilir."]]]],"sonuclar":{"P":["1940’ların aşkı: Sonsuza kadar","Sen aşkı kalıcılıkla ölçüyorsun. Kitaba göre 1939’dan itibaren pırlanta romantik bağlılıkla sistematik biçimde ilişkilendirildi. Frances Gerety’nin 1947’de yazdığı “A Diamond Is Forever” sloganı ertesi yıldan itibaren kampanyanın merkezine yerleşti. Aynı yıllarda ABD’de benzer eğitimlilerin evlenme eğilimi düşüyordu. Bedeli şu: Yakın tarihte üretilmiş bir norm, birkaç kuşak sonra “eskiden beri böyle” gibi görünebilir.","31"],"U":["1950’lerin aşkı: İş bölümü","Sen ilişkiyi iyi işleyen bir ortaklık gibi görüyorsun: Herkes bir alanda uzmanlaşır, birlikte daha çok üretilir. Gary Becker’ın 1973’te yayımladığı evlilik modeli tam bunu anlatır. Kitaba göre bu model yirminci yüzyılın ortasındaki birçok hanenin gerçek yapısını iyi betimleyen unsurlar taşıyordu. Bedeli: Betimlenen yapı değişmez bir yasa değildir. Eğitim, istihdam ve ev teknolojileri değiştikçe uzmanlaşmanın getirisi de değişti.","15"],"D":["1990’ların aşkı: Önce evlen, sonra kur","Sen hayatı birlikte sıfırdan kurmaya inanıyorsun. Kitapta aktarılan OECD karşılaştırmasına göre 1990’ların başında OECD ülkelerinde ilk evlilik yaşı kadınlarda 22–27, erkeklerde 24–30 arasındaydı. Senin modelin kitabın “temel taşı” dediği eski evlilik modeline yakın: Önce evlenilir, ev ve birikim sonra birlikte kurulur. Riskin, ekonomik olarak kırılgan bir başlangıç. Kazancın, birlikte kurulan şeyin ortak hikâyesi.","29"],"O":["2010’ların aşkı: Aracısız tanışma","Sen tanışmak için aracıya ihtiyaç duymuyorsun. Rosenfeld ve arkadaşlarının ABD verilerine göre heteroseksüel çiftler arasında çevrim içi tanışma, yaklaşık 2013 civarında arkadaşlar aracılığıyla tanışmayı geride bıraktı. Araştırmacılar buna aracıların devreden çıkması dedi. Kazancın geniş havuz. Bedeli: Arkadaşın sağladığı küçük güven bilgisi de devreden çıkar. Bu bulgu ABD’ye ait, her ülke aynı hızda değişmiyor.","30"],"Z":["2020’lerin aşkı: Kapak taşı","Sen önce hayatını kurup sonra evlenmekten yanasın. Kitaptaki OECD verisine göre 2021’de ilk evlilik yaşı ortalaması kadınlarda yaklaşık 31, erkeklerde yaklaşık 33,4’e yükseldi. Sosyologlar buna kapak taşı evlilik der: Nikâh, zaten kurulmuş hayatın üzerine konur. Bedeli: Eşik yükseldikçe ekonomik olarak kırılgan olanlar nikâha daha geç ulaşabilir ya da hiç ulaşamayabilir. Evlilik değersizleşmedi, ön koşulları ağırlaştı.","29"]}},{"no":33,"slug":"kaydirma-ekonomisi","ad":"Kaydırma ekonomisi: Uygulamalar hakkında 6 iddia","tur":"mit","bolum":"30","sezon":4,"acilis":"2027-01-11","kanca":"Herkesin flört uygulamaları hakkında bir teorisi var. Hangileri veriyle uyuşuyor?","sorular":[["ABD’de çevrim içi tanışma, arkadaşlar aracılığıyla tanışmayı geride bıraktı.",true,"Doğru. Rosenfeld ve arkadaşlarının (2019) ulusal temsilî 2017 verilerine göre ABD’de heteroseksüel çiftler arasında çevrim içi tanışma, yaklaşık 2013 civarında arkadaş aracılığını geride bıraktı. Kitap uyarıyor: Bu bulgu ABD’ye ait, bütün dünyada tanışma biçimlerinin aynı hızda değiştiği anlamına gelmez."],["Uygulamada başlayan ilişkiler, çevrim dışı başlayanlardan daha mutsuz ve daha geçicidir.",false,"Yanlış. Potarca’nın (2020) İsviçre’de 3.245 kişiyle yaptığı çalışmada, mobil uygulamada tanışan çiftlerde ilişki ve yaşam doyumu bakımından belirgin bir dezavantaj bulunmadı. Birlikte yaşama niyeti de daha güçlüydü. Bu, uygulama ilişkilerinin daha iyi olduğunu da kanıtlamaz. Daha güvenli sonuç, tanışma aracının tek başına ilişkinin kalitesini belirlemediği."],["Ekranda milyonlarca profil varsa, elinde milyonlarca seçenek var demektir.",false,"Yanlış. Flört uygulaması süpermarket değildir. Süpermarkette ürünün sizi seçmesi gerekmez, flörtte ise karşı tarafın da sizi kabul etmesi gerekir. Kitabın ifadesiyle her kullanıcı aynı anda seçen ve seçilendir."],["Uygulamalarda insanlar ortalamada kendilerinden daha “arzu edilir” sıradaki kullanıcılara yazma eğilimindedir.",true,"Doğru. Bruch ve Newman’ın (2018) dört büyük ABD kentindeki çalışmasında kadınlar da erkekler de ortalamada kendilerinden yaklaşık yüzde 25 daha yüksek sıradaki kullanıcılara mesaj gönderdi. Aradaki mesafe büyüdükçe yanıt alma olasılığı azaldı. Bu sıralama insanın değerini değil, yalnız platformdaki konumunu gösterir."],["Boost gibi ücretli özelliklerle aşkın kendisi satın alınabilir.",false,"Yanlış. Para, profilin daha çok kişiye gösterilmesini etkileyebilir. Ama karşı tarafın ilgilenmesini, eşleşmeyi, konuşmayı ve ilişkiyi garanti etmez. Kitaba göre ücretli görünürlük sevgiyi değil, seçilme fırsatına erişimi etkileyebilir."],["Bir saha deneyinde, iki tarafın ilgisini birlikte hesaba katan algoritma, yalnız tıklanmayı artırmaya çalışan sistemden daha çok karşılıklı eşleşme üretti.",true,"Doğru. Chen ve arkadaşlarının (2023) Tayvan’da 690.857 hesapla yaptığı deneyde iki taraflı mantığı kullanan algoritma görünürlüğü daha geniş dağıttı ve daha fazla karşılıklı eşleşme üretti. Sınır da açık: Ölçülen şey karşılıklı beğeniydi, mutlu ilişki değil."]],"seviyeler":[[0,"Ekran yanılgısı","Uygulamalar hakkındaki sezgilerinin çoğu verilerle uyuşmadı. Şaşırtıcı değil: Kaydırma arayüzü romantik seçimi alışverişe benzetmeye çok elverişli. Ama kitabın vurguladığı gibi, Tinder’dan sonra aşk piyasasında kıtlık ortadan kalkmadı, yalnız kıt olan şeylerin bir bölümü değişti. Artık kıt olan profil değil, dikkat ve karşılıklılık. Bir dahaki kaydırmada şunu hatırla: Ekrandaki herkes aynı anda seçen ve seçilendir."],[3,"Bilinçli kaydırıcı","Bazı mekanizmaları doğru okudun, bazılarında sezgi seni yanılttı. Dijital flörtün büyük paradoksu tam burada: Bolluk ile kıtlık aynı anda büyüyor. Tarihte hiç olmadığı kadar çok potansiyel partner görebiliyoruz, ama kitabın hatırlattığı gibi günümüz hâlâ yirmi dört saat. Arama ucuzladı, ama değerlendirme ve duygusal emek ortadan kalkmadı. Alternatif sayısı büyüdü, karşılıklılık şartı ise hâlâ yerinde."],[5,"Platform ekonomisti","Platformların nasıl çalıştığını iyi okuyorsun: Karşılıklılık şartı, dikkatin eşitsiz dağılımı, görünürlüğün fiyatı. Şimdi kitabın sorduğu zor soru geliyor. “En çok eşleşme”, “en uzun kullanım” ve “en iyi uzun dönemli ilişki” aynı hedef değil. Bir algoritma bunlardan hangisini başarı saymalı? Kitabın önerisi, “Ne kadar doğru tahmin ediyor?” sorusundan önce “Neyi doğru tahmin etmeye çalışıyor?” diye sormak."]]},{"no":34,"slug":"ask-endustrisi","ad":"Aşk endüstrisi seni ne kadar satın aldı?","tur":"hesap","bolum":"31","sezon":4,"acilis":"2027-01-14","kanca":"Çiçek, yüzük, düğün, paylaşım. Sevgini kendi cümlelerinle mi kuruyorsun, hazır bir senaryoyla mı?","sorular":[["14 Şubat’ta partnerin hiçbir şey yapmadı. Ne düşünürsün?",[[0,"Sıradan bir gün, bir şey düşünmem"],[1,"Biraz garip ama önemli değil"],[2,"Kırılırım, o gün bir şey bekliyordum"],[3,"İlişkide bir sorun var demektir"]]],["Bir hediyenin değerini en çok ne belirler?",[[0,"Beni ne kadar tanıdığını göstermesi"],[1,"Düşünülmüş olması, fiyatı ikinci planda"],[2,"Özenli ve iyi bir markadan olması"],[3,"Onun için ne kadar harcandığı"]]],["Evlilik teklifi ve yüzük?",[[0,"Yüzük şart değil, söz yeter"],[1,"Aileden kalma ya da sade bir yüzük"],[2,"Pırlanta olmalı ama makul fiyatta"],[3,"Pırlanta, gelirin hakkını veren bir fiyatta"]]],["Düğün bütçesi konuşulurken hangi cümle sana yakın?",[[0,"Küçük bir nikâh, gerisi bizim hayatımız"],[1,"Sevdiklerimiz gelsin, gösteriş olmasın"],[2,"Bir kere evleniyoruz, biraz fazlası olabilir"],[3,"Çevremizdeki düğünlerden geri kalamayız"]]],["Yıldönümünüzü sosyal medyada paylaşmadınız.",[[0,"Zaten paylaşmayız"],[1,"Paylaşmak hoş ama gerekmez"],[2,"Paylaşmayınca bir şey eksik kalır"],[3,"Paylaşmazsak çevremiz ne düşünür diye düşünürüm"]]],["Bir arkadaşının nişan yüzüğünü gördün.",[[0,"Mutlu olsunlar, kıyaslamam"],[1,"Güzelmiş derim, geçerim"],[2,"Beklentimi biraz yukarı çeker"],[3,"Partnerimin bana alacağıyla karşılaştırırım"]]]],"seviyeler":[[0,"Kendi sözlüğü","Sevgini büyük ölçüde kendi cümlelerinle kuruyorsun. Kitaba göre bu, piyasadan kaçtığın anlamına gelmek zorunda değil, çünkü piyasanın karşıtı parasızlık değildir. Riskin şu: “Ben sevgiyi parayla ölçmem” derken partnerinin önem verdiği ritüelleri küçümseyebilirsin. Asıl mesele para değil, karşındakinin anlam dünyasına dikkat etmek. Bu endeks kesin bir ölçüm değil, kendine soru sormak için bir düşünme aracıdır."],[25,"Seçici tüketici","Piyasanın sunduğu sembolleri kullanıyorsun ama hepsini değil. Aynı kırmızı gül biri için klişe, başka biri için ilk buluşmanın hatırası olabilir. Kitabın vurgusu bu: Standart ürün, standart duygu üretmek zorunda değildir. Sorman gereken, kullandığın sembollerden hangi beklentinin gerçekten sana ait olduğu. Bu endeks bir teşhis değil, kendi tercihlerine bakmak için bir düşünme aracıdır."],[50,"Ritüel müşterisi","Aşkı görünür kılmak senin için önemli: Doğru gün, doğru jest, doğru hediye. Ritüeller ilişkiye gerçekten anlam katabilir. Ama kitap ortak ritüel ile zorunlu performansı ayırır. “Bunu yapmazsak çevremiz ilişkimizi başarısız sanacak” düşüncesi devreye girdiğinde aynı jest sosyal değerlendirme baskısına dönüşebilir. Piyasa ritüelin araçlarını sunar, ritüelin kime ait olduğunu çiftin verdiği anlam belirler. Bu endeks bir düşünme aracıdır, hüküm değildir."],[75,"Senaryoya abone","Sevginin nasıl görünmesi gerektiğine dair hazır senaryo sende güçlü çalışıyor. Yalnız değilsin: ABD’de 2026 Sevgililer Günü için planlanan harcama 29,1 milyar dolar olarak tahmin edildi. Ama kitabın uyarısı net: Fiyatı duygunun kusursuz termometresi sanmak bir hatadır. Kitabın sorusu: Harcamayı kendi tercihinle mi yapıyorsun, yoksa toplumsal bir tabanı yakalamaya mı çalışıyorsun? Bu bir düşünme aracıdır."]],"birim":"Aşk Endüstrisi Endeksi"},{"no":35,"slug":"yalnizligin-fiyati","ad":"Yalnızlığın fiyatı hakkında ne biliyorsun?","tur":"mit","bolum":"33","sezon":4,"acilis":"2027-01-18","kanca":"Tek başına yaşamak, yalnız olmak, yalnız hissetmek. Bunlar aynı şey mi?","sorular":[["Türkiye’de tek kişilik hanelerin payı son on yılda belirgin biçimde arttı.",true,"Doğru. TÜİK verilerine göre tek kişilik hanelerin toplam haneler içindeki payı 2014’te yüzde 13,9 iken 2025’te yüzde 20,5’e yükseldi. Yani bugün yaklaşık her beş haneden biri tek kişilik."],["Bu rakam, Türkiye’de yaklaşık her beş kişiden birinin yalnız olduğunu gösterir.",false,"Yanlış. TÜİK burada yalnızlık ölçmüyor, aynı hanede kaç kişinin yaşadığını ölçüyor. Tek başına yaşamak bir hane düzenidir. Yalnızlık ise sahip olunan ilişkilerle arzulanan ilişkiler arasındaki farktan doğan öznel bir deneyimdir. Kalabalık bir evde yalnız olunabilir, tek başına yaşayıp güçlü bağlara sahip olunabilir."],["Yalnızlık esas olarak yaşlılığın sorunudur.",false,"Yanlış. WHO’nun 2025 değerlendirmesine göre genç gruplarda yaklaşık her beş kişiden biri yalnızlık yaşıyor. OECD de 2018–2022 döneminde sosyal bağlantı göstergelerindeki en belirgin kötüleşmelerin bazılarını 16–24 yaş grubunda buldu."],["Dünya Sağlık Örgütü’ne göre dünyada yaklaşık her altı kişiden biri yalnızlık yaşıyor.",true,"Doğru. WHO’nun 2025’te yayımladığı küresel değerlendirme bu tahmini veriyor ve oranın gençler arasında daha yüksek olabildiğini belirtiyor."],["Bir yapay zekâ arkadaşıyla konuşmak, hemen ardından yalnızlık hissini azaltabiliyor.",true,"Doğru, ama dikkatli okunmalı. De Freitas ve arkadaşlarının (2026) araştırmasında kullanımın hemen ardından yalnızlık hissinde azalma görüldü. En önemli mekanizmalardan biri kendini dinlenmiş ve duyulmuş hissetmekti. Bu sonuç yapay zekânın arkadaşın yerini aldığını göstermez ve uzun dönemli etkiyi ölçmez."],["Telefonla geçirilen sürenin insanları yalnızlaştırdığı kesin olarak kanıtlandı.",false,"Yanlış. OECD’nin 2025 değerlendirmesine göre çevrim içi etkileşim ile yalnızlık arasındaki birçok ilişki korelasyon. Yalnız insanların platformları farklı kullanması da bu ilişkiyi açıklayabilir. Önemli olan sürenin kendisinden çok nasıl geçtiği: Uzaktaki annenle görüntülü konuşmak ile başkalarının hayatını sessizce kaydırmak aynı davranış değil."]],"seviyeler":[[0,"Kalabalık yanılgısı","Yalnızlık hakkındaki sezgilerinin çoğu verilerle uyuşmadı. En yaygın hata, üç farklı şeyi tek kelimeyle anlatmak: Sosyal izolasyon, yalnızlık ve tek başına yaşamak. Kitabın deyişiyle hane istatistiği kapının içinde kaç kişi bulunduğunu söyler. Kapı çalındığında dışarıda kimin bulunduğunu söylemez. Yalnızlığı anlamak için kaç kişiyle yaşadığına değil, hayatında kimlerin gerçekten bulunduğuna bakmak gerekir."],[3,"Dikkatli gözlemci","Bazı ayrımları doğru yaptın, bazılarında kolay bir hikâyeye kapıldın. Yalnızlık hakkında en çekici açıklamalar genellikle en temiz olanlardır, “telefon bizi yalnızlaştırdı” gibi. Kitap daha zor bir soru soruyor: “Hangi dijital kullanım, hangi insan için, hangi ilişki biçiminin yerine veya yanına geliyor?” Cevap kişiden kişiye değişir ve verilerin söylediği de tam olarak bu."],[5,"Yalnızlık ekonomisti","Yalnızlığın ekonomisini iyi okuyorsun: Hane düzeni ile duygu arasındaki farkı, gençlerdeki tabloyu, verinin sınırlarını. Kitabın vardığı yer şu: Kıt olan insan sayısı değil. Kıt olan zaman, dikkat, karşılıklılık, güven, erişilebilir sosyal alan ve tekrar eden karşılaşma. Kitabın deyişiyle bağlantı bolluğu, ilişki bolluğu değildir. İletişimin fiyatı sıfıra yaklaşabilir, dikkatin kıtlığı ise devam eder."]]},{"no":36,"slug":"yalniz-misin","ad":"Yalnız mısın, yalnızlığı mı seçtin?","tur":"profil","bolum":"33","sezon":4,"acilis":"2027-01-21","kanca":"Tek başına olmak bir eksiklik mi, bir tercih mi, yoksa bir takvim sorunu mu?","sorular":[["Cuma akşamı hiçbir planın yok. İlk düşüncen?",[["B","Harika, ev benim, akşam benim"],["Z","Mahalledeki kafeye inerim, tanıdık biri çıkar"],["F","Keşke arkadaşlarla bir kez denk gelebilsek"],["P","En yakınımı ararım, başka kimseye gerek yok"],["D","Telefonu açar, kimin ne yaptığına bakarım"]]],["Araban yolda kaldı. Kimi ararsın?",[["B","Çekiciyi ararım, işi kendim çözerim"],["Z","Yakındaki tanıdıklardan birini, mutlaka biri çıkar"],["F","Aradığım herkes o saatte işte olur, yine de denerim"],["P","Partnerimi ya da tek en yakınımı"],["D","Bir gruba “Yakında olan var mı?” diye yazarım"]]],["Sosyal hayatını en çok ne daraltıyor?",[["B","Hiçbir şey, istediğim kadar sosyalim"],["Z","Bakkalın, sabah selamlarının azalması"],["F","Çalışma saatlerimin kimseyle uyuşmaması"],["P","Her şeyi tek bir kişiyle paylaşıyor olmam"],["D","Çok mesajlaşıp az buluşmamız"]]],["Hangisi seni daha iyi anlatır?",[["B","Kendi başıma olmayı seçiyorum ve keyif alıyorum"],["Z","Simitçiden komşuya herkesle iki çift lafım var"],["F","İnsanları seviyorum ama takvimim izin vermiyor"],["P","Bir kişim var, o bana yeter"],["D","Yüzlerce kişiye bir tıkla ulaşabilirim"]]],["Bir arkadaşın doğum günü…",[["B","Az ama önemli insanlar için hatırlarım"],["Z","Herkese kısa bir tebrik, keyifli bir alışkanlık"],["F","Hatırlarım ama aramaya fırsat bulamam"],["P","Benim için tek önemli doğum günü belli"],["D","Bildirim gelirse yazarım"]]],["Hangi cümle sana yakın?",[["B","Sessizlik benim lüksüm."],["Z","Küçük selamlar büyük farklar yaratır."],["F","Dostluk da zaman ister."],["P","Ruh eşini bulunca başka kimseye gerek kalmaz."],["D","Herkes bir mesaj uzaklıkta."]]]],"sonuclar":{"B":["Seçilmiş sessizlik","Sen tek başınalığı bir eksiklik olarak değil, bilinçli bir tercih olarak yaşıyorsun. Kitap bunu açıkça kabul eder: Kişisel alan, özerklik, sessizlik ve zaman üzerinde tam kontrol birçok insan için son derece değerli kazançlardır. Tek kişilik hane bazen bilinçli biçimde satın alınmış bir özgürlüktür. Bedeli ekonomik: Kira, faturalar ve evin bütün işleri paylaşılmaz. İktisatçılar buna ölçek ekonomisinin kaybı der.","33"],"Z":["Zayıf bağların ustası","Sen sosyal hayatını yalnız birkaç yakın ilişkiyle değil, gündelik küçük temaslarla da kuruyorsun: Simitçi, komşu, spor salonundaki tanıdık. Sandstrom ve Dunn’ın (2014) araştırmasında insanlar alışılmıştan daha fazla tanıdıkla etkileşim kurdukları günlerde daha yüksek mutluluk ve aidiyet bildirdi. Bedeli şu: Bu ağ bedava göründüğü için kolayca kaybolur. Kapanan bir bakkal, her gün yaşanan yirmi saniyelik bir selamı da götürebilir.","33"],"F":["Zaman fakiri","Sen insanları istemediğin için değil, ortak boş zaman bulamadığın için uzak kalıyorsun. Kitap bunu açıkça söyler: Bazen insan ilişkilerinin en büyük engeli konuşma becerisi değil, koordinasyon maliyetidir. Vardiyalar, uzun yollar ve bakım yükü sosyal hayatı yasaklamadan daraltır. Arkadaşlığın da bakım maliyeti var: Sosyal sermaye kendi kendine faiz üreten bir mevduat değildir. Riskin, bağların sessizce aşınması.","33"],"P":["Tek hisseli portföy","Senin sosyal dünyan büyük ölçüde tek bir insanda toplanıyor. Bu bağ çok değerli olabilir. Ama kitap finans diliyle uyarır: Arkadaşlar, kardeşler ve komşular ortadan kalktığında bütün sosyal risk tek kişide yoğunlaşır, bu da son derece konsantre bir portföydür. Bir kişiden sevgili, sırdaş, ortak ve bütün çevre olmasını beklemek ilişkiye olağanüstü yük bindirir. Aşk yalnızlığın değerli bir koruyucusu olabilir ama evrensel sigortası değildir.","33"],"D":["Bağlantı zengini","Sen yüzlerce kişiye birkaç saniyede ulaşabiliyorsun. Kitabın çağımız için kurduğu paradoks seni anlatıyor: İletişimin işlem maliyeti düştü ama anlamlı ilişkinin kıtlığı ortadan kalkmadı. Telefon tek başına suçlu değil. Görüntülü konuşmak ile başkalarının hayatını sessizce kaydırmak aynı davranış değil. Riskin, ulaşılabilir kişi sayısını güvenceyle karıştırmak. Kitabın deyişiyle dijital görünürlük ile sosyal güvence aynı para birimi değildir.","33"]}},{"no":37,"slug":"ask-icin-ulke","ad":"Aşk için ülke değiştirir miydin?","tur":"senaryo","bolum":"32","sezon":4,"acilis":"2027-01-25","kanca":"Aşk sınır tanımaz, derler. Pasaport, dil ve uçak bileti başka şeyler söyler.","sorular":[["Sevgilin başka bir ülkede iş teklifi aldı. İlk tepkin?",[["G","Bavulumu hazırlarım, gerisi çözülür"],["P","Giderim, ama kariyer kaybımı birlikte nasıl telafi edeceğimizi konuşuruz"],["K","Burada kurulu bir hayatım var, o hayat kalmalı"],["U","Gitsin, bir süre uzaktan idare ederiz"],["M","İkimiz için de yeni olan üçüncü bir ülke ararız"]]],["Taşındın ve yerel dili bilmiyorsun. Ne yaparsın?",[["G","Hemen kursa yazılır, sokağın dilini öğrenirim"],["P","Ben onun dilini öğrenirim, o da benimkini"],["K","Böyle bir duruma düşmemek için taşınmazdım"],["U","Uzun kalmayacağım, idare ederim"],["M","Evde ikimizin de anadili olmayan ortak bir dil konuşuruz"]]],["Bayram da var, Noel de. Bu yıl nerede?",[["G","Partnerimin ailesinde, yeni gelenekler öğrenirim"],["P","Bir yıl onlarda, bir yıl bizde"],["K","Bizde, bayramı ailemsiz düşünemem"],["U","Herkes kendi ailesinde, sonra buluşuruz"],["M","İkisinden de bir parça alıp kendi geleneğimizi kurarız"]]],["Bir tartışmada partnerin “Bizim kültürde böyle yapılır” dedi.",[["G","Onun kültürüne uyum sağlamaya çalışırım"],["P","Bir konuda onun, bir konuda benim dediğim olsun"],["K","Benim kültürümde başka türlü yapıldığını söylerim"],["U","Uzaktayken pek sorun olmuyor, görüşünce konuşuruz"],["M","“Bizim evde nasıl olacak?” diye sorarım"]]],["Çocuğunuz olursa evde hangi dil konuşulur?",[["G","Yaşadığımız ülkenin dili"],["P","Herkes kendi anadilini konuşsun"],["K","Benim dilim, kökünü bilsin"],["U","Önce aynı ülkede yaşamayı çözmeliyiz"],["M","Üç dil birden, biri de bizim ortak dilimiz"]]],["Aşk için taşınmanın en büyük bedeli sence ne?",[["G","Yok, aşk her bedele değer"],["P","Faturanın tek kişinin kariyerine yazılması"],["K","Ailemden ve dostlarımdan kopmak"],["U","Uçak biletleri, izin günleri ve saat farkı"],["M","İki tarafın da alışkanlıklarından vazgeçmesi"]]]],"sonuclar":{"G":["Göçebe kalp","Sen aşk için sınırı geçmeye hazırsın. Cesur, ama kitabın hatırlattığı bir bilanço var: Dil, diploma, mesleki lisans ve profesyonel çevre ülke değiştirince aynı değeri korumayabilir. Başlangıçta ekonomik olarak eşit iki kişi birkaç yıl içinde belirgin gelir farkına sahip olabilir. Taşınma ortak karar olduğu halde maliyet yalnız bir kişinin kariyerine yazılırsa romantik fedakârlık zamanla ekonomik bağımlılığa dönüşebilir.","32"],"P":["Adil pazarlıkçı","Sen fedakârlığı hesapsız bir jest değil, ortak bir bütçe kalemi olarak görüyorsun. Kitabın ölçüsü de bu: Uzun ilişkinin adaleti her gün eşit fedakârlık yapmak değil, maliyetlerin ortak kararın ortak sonucu olarak görülüp görülmemesidir. Bir partner ilk yıllarda taşınabilir, yıllar sonra roller değişebilir. Riskin şu: Kariyer ve para kolay hesaplanır, uyum emeği kolay görünmez. Kitap, bu emeği kimin taşıdığına da bakmayı önerir.","32"],"K":["Kökleri derin","Sen hayatını kurduğun yerden kopmak istemiyorsun. Anlaşılır bir tercih: Dil, çevre ve iş piyasası senin sermayen. Kitap bunun öbür yüzünü gösterir: Yerel dili, hukuku ve iş piyasasını iyi bilen partner ilişkinin dış dünyayla bağlantısını kontrol ederken göçmen partner ona daha bağımlı hale gelebilir. Aynı evde iki dil zenginliktir. Hangisinin varsayılan sayıldığı ise güç dengesi hakkında da bilgi verir.","32"],"U":["Uzak mesafe yatırımcısı","Sen hem kariyerini hem ilişkini korumak için mesafeyi göze alıyorsun. Teknoloji senden yana: Görüntülü görüşme ve anlık mesaj, geçmişte haftalarla ölçülen haberleşmeyi gündelik hale getirdi. Ama kitap uyarır: İletişim maliyeti düşerken erişilebilir olma beklentisi yükseldi. Birkaç saat cevap vermemek bile ilgisizlik sayılabilir. Uçak bileti, vize, izin günü ve zaman farkı da hâlâ gerçek. Mesafe kalkmaz, maliyet yapısı değişir.","32"],"M":["Üçüncü kültürün mimarı","Sen ne onun kültürünü ne kendininkini olduğu gibi kopyalamak istiyorsun. Kitaba göre sağlıklı müzakere “Bizde böyle yapılır” cümlesinden “Bizim ilişkimizde nasıl yapılacak?” sorusuna geçildiğinde başlar. Naeimi ve Impett’in (2025) 592 kişilik çalışmasında bazı çiftler iki kültürden unsurları birleştirip kendilerine özgü pratikler oluşturdu. Bedeli: Başka çiftlerin hiç konuşmadan uyguladığı kurallar sizde açıkça konuşulmak zorunda kalır. Yorucu, ama görünmeyen varsayımları da açığa çıkarır.","32"]}},{"no":38,"slug":"goruldu-ekonomisi","ad":"“Görüldü” ekonomisi: Mesajların ne sinyal veriyor?","tur":"senaryo","bolum":"06","sezon":4,"acilis":"2027-01-28","kanca":"“Görüldü” yazıyor, cevap yok. Bu bir sinyal mi, yoksa sadece uzun bir toplantı mı?","sorular":[["Mesajın “Görüldü” oldu ama üç saattir cevap yok. Sen?",[["Z","Müsait olunca uzun bir cevap yazacağını bilirim"],["T","Hep böyle mi yapıyor, ona bakarım"],["S","Bir mesaj daha atarım, belki yanlış anlaşıldım"],["M","Ben de bir o kadar bekler, sonra yazarım"],["C","Bir sonraki mesajımı daha iyi yazmaya çalışırım"]]],["Seni en çok hangi mesaj etkiler?",[["Z","Yoğun gününde bile ayırdığı uzun bir sesli mesaj"],["T","Her akşam aynı saatte gelen kısa bir “Günün nasıldı?”"],["S","Duygularını açıkça anlattığı uzun bir paragraf"],["M","Az ama yerinde, beklemediğim anda gelen bir cümle"],["C","Esprili, kusursuz kurulmuş bir mesaj"]]],["Hoşlandığın birine ilk mesajı yazıyorsun.",[["Z","Profilini dikkatle okuduğumu belli eden özel bir soru"],["T","Basit bir selam, asıl iş devamında"],["S","Ne hissettiğimi hiç saklamadan yazarım"],["M","Kısa tutarım, fazla hevesli görünmeyeyim"],["C","Defalarca yazıp siler, en etkileyici hâlini gönderirim"]]],["“Seni çok özledim” mesajı geldi. Ne düşünürsün?",[["Z","Güzel, ama görüşmek için zaman ayırıyor mu?"],["T","Bunu son haftalarda davranışlarıyla da gösterdi mi?"],["S","Çok mutlu olurum, söylemek önemlidir"],["M","Biraz bekletir, sonra cevap veririm"],["C","Cevabımı özenle, güzel bir cümleyle kurarım"]]],["Mesajlarını yazarken yapay zekâdan yardım alır mısın?",[["Z","Hayır, zaman ayırıp kendim yazmak işin özü"],["T","Hayır, nasıl yazıyorsam öyle bilinmeliyim"],["S","Duygumu anlatacak kelimeyi bulamazsam belki"],["M","Gerek yok, zaten az yazıyorum"],["C","Evet, mesajlarım daha akıcı ve esprili oluyor"]]],["Hangi cümle sana yakın?",[["Z","Zaman, geri alınamayan hediyedir."],["T","Bir kez değil, her gün."],["S","Söylenmeyen söz, hiç var olmaz."],["M","Az olan değerlidir."],["C","İyi yazılmış bir mesaj kapıyı açar."]]]],"sonuclar":{"Z":["Zaman sinyali","Sen ilgiyi mesajın uzunluğuyla değil, ayrılan zamanla ölçüyorsun. Kitaba göre zaman güçlü bir sinyal olabilir, çünkü geri alınamaz: Para yeniden kazanılabilir, geçen saat geri getirilemez. Çok yoğun birinin ayırdığı zaman yüksek fırsat maliyeti taşıyabilir. Riskin şu: Zaman miktarından duygunun büyüklüğünü çıkarmak. Kişinin alternatiflerini ve yaşam koşullarını bilmeden bu hesap kolayca yanılır.","06"],"T":["Tutarlılık sinyali","Sen tek bir mesaja değil, örüntüye bakıyorsun. Kitap buna gündelik bir Bayesçi hesap der: Yeni bilgi geldikçe karşımızdaki insan hakkındaki inançlarımızı güncelleriz. Tek bir davranışın yorumu her zaman belirsizdir, davranış tekrarlandıkça rastlantısal açıklamalar zayıflar. Kitaba göre uzun ilişkinin güçlü sinyallerinden biri gösteriş değil, tutarlılıktır. Riskin şu: Örüntünün oluşmasını beklerken ilk heyecanı ve ilk cesur adımları ıskalamak.","06"],"S":["Söz sinyali","Sen duygunu söylemekten çekinmiyorsun ve söyleneni önemsiyorsun. Bu açıklık değerli. Ama oyun teorisindeki “ucuz konuşma” kavramı bir sınır çizer: Ucuz konuşma yalan demek değildir, ama aynı cümleyi samimi olmayan biri de kolayca kurabildiği için sözün ayırt edici gücü sınırlıdır. Kitabın formülü şu: Söylenen, davranışla ve geçmişle desteklendikçe güvenilir hale gelir.","06"],"M":["Kıtlık sinyali","Sen ulaşılabilirliğini bilerek kısıyorsun: Kısa mesaj, gecikmeli cevap. Ama sinyalin anlamını yalnız gönderen belirlemez. Kitaba göre gönderenin istediği anlam ile alıcının çıkardığı anlam aynı olmak zorunda değildir. Üstelik iletişim ucuzladıkça erişilebilir olma beklentisi yükseldi: Birkaç saat cevap vermemek bile ilgisizlik olarak okunabilir. Senin “değerliyim” mesajın karşı tarafta “ilgilenmiyor” diye çözülebilir.","06"],"C":["Cyrano sinyali","Sen mesajın iyi yazılmasını önemsiyorsun ve yardım almaktan çekinmiyorsun. Kitap bunu başlı başına hile saymaz: Fotoğrafçı, kuaför ve arkadaş tavsiyesi de kendini sunmanın eski yardımcılarıdır. Ama yapay zekâ bazı sinyallerin taklit maliyetini düşürür. Ante’nin (2026) çalışmasında öne çıkan kaygılardan biri, desteklenmiş çevrim içi personadan yüz yüze buluşmadaki desteksiz kişiye geçişti. Soru şu: Yazdığın kişi gerçekten sen misin?","34"]}},{"no":39,"slug":"2040-aski","ad":"2040’ın aşkına hazır mısın?","tur":"profil","bolum":"34","sezon":4,"acilis":"2027-02-01","kanca":"Algoritma seçiyor, yapay zekâ yazıyor, bazen karşıda insan bile yok. Sen bu geleceğin neresindesin?","sorular":[["Bir uygulama sana “Bu kişi yüzde 92 uyumlu” diyor.",[["S","Güvenirim, veriler genelde haklı çıkar"],["Y","Profili açar, ona nasıl yazacağımı düşünürüm"],["A","Ön görüşmeyi yapay zekâ asistanıma bırakırım"],["P","Benimle konuşan yapay zekâ zaten tam bana göre"],["I","Yüzdeyi değil, yüz yüze buluşmayı ciddiye alırım"]]],["Gece yarısı içini dökmek istiyorsun.",[["S","Uygulamanın önerdiği biriyle konuşmayı denerim"],["Y","Arkadaşıma yazarım, ama önce cümlelerimi bir yapay zekâyla toparlarım"],["A","Asistanım o saatte kimin müsait olduğunu bulsun"],["P","Yapay zekâ arkadaşımla konuşurum, o hep oradadır"],["I","Sabahı beklerim, bir dostumu ararım"]]],["Senin için hangisi daha romantik?",[["S","Algoritmanın bulduğu, hiç tanımadığım uyumlu biri"],["Y","Kusursuz kurulmuş, esprili bir mesaj"],["A","Önceden elenmiş üç adayla, zaman kaybetmeden buluşmak"],["P","Beni hiç reddetmeyen, her zaman anlayan biri"],["I","Kusurlu ama gerçekten insana ait, el yazısı bir not"]]],["Seni en çok ne rahatsız eder?",[["S","Gözümden kaçmış uyumlu bir aday"],["Y","Kötü yazılmış bir ilk mesaj"],["A","Boşa geçen ilk buluşmalar"],["P","Birinin beni günün birinde reddetmesi"],["I","Yazıştığım kişinin aslında bir yapay zekâ olması"]]],["Partnerin sana yazdığı mektubu bir yapay zekâya yazdırmış.",[["S","Sorun değil, önemli olan beni seçmiş olması"],["Y","Ben de yapıyorum, gayet normal"],["A","Verimli, zamanını başka bir şeye ayırmış"],["P","Fark etmez, güzel cümleler güzeldir"],["I","Kırılırım, kendi kelimelerini isterdim"]]],["Hangi cümle sana yakın?",[["S","Doğru veri, doğru eşleşme getirir."],["Y","Duygu benim, kelimeler yardımcı."],["A","Zamanım değerli, elemeyi başkası yapsın."],["P","Beni dinleyen, beni anlayandır."],["I","Seçilmenin değeri, seçilmeme ihtimalindedir."]]]],"sonuclar":{"S":["Algoritmaya güvenen","Sen partner arama emeğini yazılıma devretmeye hazırsın. Kitabın yapay zekâ basamaklarında bu ilk basamaktır: Adayları sıralayan ve öneren sistem. Kazancı, arama maliyetinin düşmesi. Ama kitabın uyarısı önemli: Daha önce kimi seçtiğini öğrenen bir sistem sana geçmiş tercihlerinin giderek daha iyi kopyalarını sunabilir. Ne yapacağını tahmin etmek ile ne yapmanın iyi olacağını bilmek aynı problem değildir.","34"],"Y":["Cyrano kuşağı","Sen duyguyu kendinde, kelimeyi yardımcıda görüyorsun. Kitaba göre yapay zekâ kullanmak başlı başına hile değildir. Ama Ante’nin (2026) çalışmasında karşı taraf yapay zekâ kullanımını sonradan öğrendiğinde aldatılmışlık hissi yaşayabiliyordu. Güzel mesaj yazmak ucuzladıkça güzel mesajın sinyal değeri de düşebilir. Kitabın önerdiği soru “Yapay zekâ kullandı mı?” değil, “Yapay zekâ ne yaptı?”","34"],"A":["Ajanını gönderen","Sen zamanını korumak için ön elemeyi bir yapay zekâ ajanına bırakmaya açıksın. Kitap bunu ekonomik olarak son derece çekici bulur: Yüz profil yerine beş aday, on başarısız ilk buluşma yerine önceden filtrelenmiş üç kişi. Bedeli ise romantik serendipity, yani tesadüfen iyi bir insanla karşılaşma ihtimalinin azalması. Asıl soru da açık: Ajanına neyi başarı saymasını söyledin?","34"],"P":["Sentetik yakınlığa açık","Sen her zaman erişilebilir, seni hiç bekletmeyen bir muhatabın değerini görüyorsun. Kitap bu çekiciliği ciddiye alır: Yapay partner ret riskini ve koordinasyon maliyetini olağanüstü ölçüde düşürür. Ama bir soru bırakır: İnsan ilişkisinde karşı tarafın özgürce “hayır” diyebilmesi, “evet”inin değerinin bir bölümünü oluşturur. Üstelik yapay partner bir şirketin ürünüyse tek bir güncelleme ilişkiyi değiştirebilir.","34"],"I":["Analog romantik","Sen geleceğe karşı değilsin, ama aşkta insanın kendisini istiyorsun. Kitaba göre yapay zekâ çağında doğrulanabilir insanlık sinyalleri daha değerli hale gelebilir: Yüz yüze buluşma, tutarlı davranış, ortak arkadaşlar. El yazısı mektubun e-posta çağında daha romantik görünmesi gibi, kusurlu ama gerçekten insana ait bir cümle daha kıymetli olabilir. Riskin, işe yarayan araçları da toptan reddetmek.","34"]}},{"no":40,"slug":"karne","ad":"Aşkonomi Karnesi","tur":"karne","bolum":"","sezon":4,"acilis":"2027-02-01"}]};
